        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('10041111-0000-4000-8000-000000000001', 'What did Lencho hope for as he gazed at the north-eastern sky?', '{"A":"A mild snowstorm","B":"A downpour or at least a shower for his ripe cornfield","C":"A sunny harvest week","D":"Visit from the postmaster"}'::jsonb, 'B', 'MCQ', 'English', 'A Letter to God (Prose)', 1, 'His ripe cornfield needed rain for a good harvest.', NULL, NULL, 'His ripe cornfield needed rain for a good harvest.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000002', 'Why did Lencho call the large raindrops "ten cent pieces" and smaller ones "five cent pieces"?', '{"A":"They looked silver","B":"Rain promised a rich corn harvest that would bring money","C":"He collected coins in rain","D":"They melted quickly"}'::jsonb, 'B', 'MCQ', 'English', 'A Letter to God (Prose)', 1, 'Rain meant prosperity and cash from crops.', NULL, NULL, 'Rain meant prosperity and cash from crops.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000003', 'How many pesos did Lencho actually receive in the envelope from the post office?', '{"A":"100 pesos","B":"70 pesos","C":"50 pesos","D":"30 pesos"}'::jsonb, 'B', 'MCQ', 'English', 'A Letter to God (Prose)', 1, 'The postmaster and staff collected 70 pesos out of 100.', NULL, NULL, 'The postmaster and staff collected 70 pesos out of 100.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000004', 'Who did Lencho call "a bunch of crooks" in his second letter to God?', '{"A":"The hailstorm clouds","B":"The post office employees","C":"His neighbours","D":"His sons"}'::jsonb, 'B', 'MCQ', 'English', 'A Letter to God (Prose)', 1, 'He suspected the postal staff stole the missing 30 pesos.', NULL, NULL, 'He suspected the postal staff stole the missing 30 pesos.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000005', 'The central situational irony of "A Letter to God" lies in:', '{"A":"Hail ruining ripe corn","B":"Lencho suspecting the very people who selflessly donated money to him","C":"The postmaster laughing at first","D":"Postage stamp costing too much"}'::jsonb, 'B', 'MCQ', 'English', 'A Letter to God (Prose)', 1, 'Kind donors were branded thieves by Lencho.', NULL, NULL, 'Kind donors were branded thieves by Lencho.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000006', 'What quality of the postmaster is highlighted when he contributes part of his salary?', '{"A":"Shrewdness","B":"Empathy, generosity, and respect for Lencho''s faith","C":"Curiosity only","D":"Jealousy"}'::jsonb, 'B', 'MCQ', 'English', 'A Letter to God (Prose)', 1, 'He acted out of compassion not to shake Lencho''s faith.', NULL, NULL, 'He acted out of compassion not to shake Lencho''s faith.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000007', 'Why did Lencho say the hailstones were like "new silver coins" initially, and what happened after the storm passed?', NULL, NULL, 'VSA', 'English', 'A Letter to God (Prose)', 2, 'Initially he joyfully hoped for rain to help crops, mistaking early hail pellets for silver coins. After an hour of hailstorm, the field looked white as if covered with salt, leaving zero leaves or corn intact.', 'Initial metaphor (1M) + Destruction outcome (1M)', NULL, 'Initially he joyfully hoped for rain to help crops, mistaking early hail pellets for silver coins. After an hour of hailstorm, the field looked white as if covered with salt, leaving zero leaves or corn intact.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000008', 'How did the postmaster resolve the dilemma of answering Lencho''s letter?', NULL, NULL, 'VSA', 'English', 'A Letter to God (Prose)', 2, 'Seeing Lencho''s unshakeable faith required more than goodwill, ink, and paper, he contributed part of his salary and collected donations from postal employees and friends as an "act of charity".', 'Need for money (1M) + Collection effort (1M)', NULL, 'Seeing Lencho''s unshakeable faith required more than goodwill, ink, and paper, he contributed part of his salary and collected donations from postal employees and friends as an "act of charity".', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000009', 'Why did Lencho NOT show the slightest surprise upon seeing money inside the envelope?', NULL, NULL, 'VSA', 'English', 'A Letter to God (Prose)', 2, 'Such was Lencho''s absolute, unquestioning confidence in God that he believed God could neither make a mistake nor deny what he requested; he grew angry only because 30 pesos seemed missing.', 'Unshakeable faith (2M)', NULL, 'Such was Lencho''s absolute, unquestioning confidence in God that he believed God could neither make a mistake nor deny what he requested; he grew angry only because 30 pesos seemed missing.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000000a', '(i) Compare Lencho''s attitude toward nature before and after the hailstorm. (ii) What motivated the postmaster to sign the reply merely "God"? (iii) Identify one example of contrast between rural innocence and realistic generosity. (iv) State the theme of the story.', NULL, NULL, 'CASE', 'English', 'A Letter to God (Prose)', 4, '(i) Hopeful confidence -> utter despair ("not a leaf remained"). (ii) He did not want Lencho to lose faith in divine help or feel indebted to strangers. (iii) Lencho''s literal belief in postal delivery to Heaven vs postmaster''s quiet human kindness. (iv) Unwavering faith vs human charity and situational irony.', '4 × 1M = 4M', 'Read context: Lencho, a hardworking farmer living atop a low hill overlooking his kidney-bean and corn valley, writes directly to God after a devastating hailstorm strips every crop bare.', '(i) Hopeful confidence -> utter despair ("not a leaf remained"). (ii) He did not want Lencho to lose faith in divine help or feel indebted to strangers. (iii) Lencho''s literal belief in postal delivery to Heaven vs postmaster''s quiet human kindness. (iv) Unwavering faith vs human charity and situational irony.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000000b', 'Write a short analytical paragraph on whether Lencho''s response in the second letter makes him ungrateful or tragically naive.', NULL, NULL, 'CASE', 'English', 'A Letter to God (Prose)', 4, 'Lencho appears ungrateful on the surface because he calls his benefactors "crooks", yet psychologically it stems from pure childlike faith rather than malice: knowing only God could send help, any shortfall seems possible only through human interference. Thus his suspicion evokes sympathy alongside irony.', 'Clear stance (1M) + Textual reasoning (2M) + Conclusion (1M)', NULL, 'Lencho appears ungrateful on the surface because he calls his benefactors "crooks", yet psychologically it stems from pure childlike faith rather than malice: knowing only God could send help, any shortfall seems possible only through human interference. Thus his suspicion evokes sympathy alongside irony.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000000c', 'Imagine the postmaster writes a diary entry the evening after reading Lencho''s second letter. Capture his mixed feelings of shock, amusement, disappointment, and quiet resolve.', NULL, NULL, 'LA', 'English', 'A Letter to God (Prose)', 5, 'Format: Date/Time + first-person reflection. Postmaster expresses stunned laughter upon reading "bunch of crooks", recalls how earnestly staff pooled 70 pesos, feels momentary sting at being misjudged, yet concludes he is glad Lencho''s faith in God remained unbroken even at the cost of misunderstanding them.', 'Diary tone & voice (1.5M) + Emotional contrast & details (2.5M) + Reflection (1M)', NULL, 'Format: Date/Time + first-person reflection. Postmaster expresses stunned laughter upon reading "bunch of crooks", recalls how earnestly staff pooled 70 pesos, feels momentary sting at being misjudged, yet concludes he is glad Lencho''s faith in God remained unbroken even at the cost of misunderstanding them.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000000d', 'Where did the historic 10 May 1994 inauguration ceremony take place?', '{"A":"Cape Town Harbour","B":"Union Buildings amphitheatre in Pretoria","C":"Robben Island","D":"Johannesburg Stadium"}'::jsonb, 'B', 'MCQ', 'English', 'Nelson Mandela: Long Walk to Freedom', 1, 'Union Buildings sandstone amphitheatre in Pretoria.', NULL, NULL, 'Union Buildings sandstone amphitheatre in Pretoria.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000000e', 'What did "Apartheid" signify in South Africa?', '{"A":"Industrial growth","B":"Racial discrimination and segregation favouring whites over non-whites","C":"Equal voting rights","D":"Religious unity"}'::jsonb, 'B', 'MCQ', 'English', 'Nelson Mandela: Long Walk to Freedom', 1, 'System of institutionalised racial supremacy.', NULL, NULL, 'System of institutionalised racial supremacy.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000000f', 'According to Mandela, what are the "twin obligations" every human being has in life?', '{"A":"Wealth and fame","B":"Obligation to family/parents/wife/children AND obligation to community/country","C":"Military and business","D":"Law and religion"}'::jsonb, 'B', 'MCQ', 'English', 'Nelson Mandela: Long Walk to Freedom', 1, 'Apartheid made fulfilling both impossible for a Black South African.', NULL, NULL, 'Apartheid made fulfilling both impossible for a Black South African.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000010', 'How did Mandela define true "courage" after watching comrades risk their lives?', '{"A":"Complete absence of fear","B":"The triumph over fear","C":"Physical strength only","D":"Avoiding danger"}'::jsonb, 'B', 'MCQ', 'English', 'Nelson Mandela: Long Walk to Freedom', 1, '"The brave man is not he who does not feel afraid, but he who conquers that fear."', NULL, NULL, '"The brave man is not he who does not feel afraid, but he who conquers that fear."', 'EASY', true),
        ('10041111-0000-4000-8000-000000000011', 'What "extraordinary human disaster" had lasted far too long before 10 May 1994?', '{"A":"Floods","B":"Apartheid white minority rule","C":"World War","D":"Drought"}'::jsonb, 'B', 'MCQ', 'English', 'Nelson Mandela: Long Walk to Freedom', 1, 'Decades of racial oppression in South Africa.', NULL, NULL, 'Decades of racial oppression in South Africa.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000012', 'Mandela felt both the oppressed and the oppressor are:', '{"A":"Free citizens","B":"Robbed of their humanity (prisoners of hatred vs chains)","C":"Equally wealthy","D":"Indifferent"}'::jsonb, 'B', 'MCQ', 'English', 'Nelson Mandela: Long Walk to Freedom', 1, '"The oppressor must be liberated just as surely as the oppressed."', NULL, NULL, '"The oppressor must be liberated just as surely as the oppressed."', 'EASY', true),
        ('10041111-0000-4000-8000-000000000013', 'Why were two national anthems sung on the day of the inauguration?', NULL, NULL, 'VSA', 'English', 'Nelson Mandela: Long Walk to Freedom', 2, 'Whites sang "Nkosi Sikelel -iAfrika" and Blacks sang "Die Stem" (the old anthem) — symbolising reconciliation, mutual respect, and unity between the two formerly divided communities.', 'Both anthems / groups (1M) + Reconciliation meaning (1M)', NULL, 'Whites sang "Nkosi Sikelel -iAfrika" and Blacks sang "Die Stem" (the old anthem) — symbolising reconciliation, mutual respect, and unity between the two formerly divided communities.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000014', 'How did Mandela''s understanding of "freedom" evolve from boyhood to adulthood?', NULL, NULL, 'VSA', 'English', 'Nelson Mandela: Long Walk to Freedom', 2, 'As a boy, freedom meant running in fields and swimming in streams; as a student, transitory freedoms like staying out at night; finally as an adult, he realised freedom was indivisible — his people''s chains were his own chains.', 'Boyhood -> Youth -> Collective adulthood (2M)', NULL, 'As a boy, freedom meant running in fields and swimming in streams; as a student, transitory freedoms like staying out at night; finally as an adult, he realised freedom was indivisible — his people''s chains were his own chains.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000015', 'Why does Mandela thank the international leaders gathered in Pretoria?', NULL, NULL, 'VSA', 'English', 'Nelson Mandela: Long Walk to Freedom', 2, 'Their presence showed global recognition of South Africa''s non-racial democratic victory for justice, peace, and human dignity after years of international isolation.', 'Global solidarity & legitimacy (2M)', NULL, 'Their presence showed global recognition of South Africa''s non-racial democratic victory for justice, peace, and human dignity after years of international isolation.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000016', '(i) Explain why love comes more naturally to the human heart than hate according to Mandela. (ii) What sustained his belief in human goodness during darkest prison days? (iii) How does prejudice imprison the oppressor? (iv) Give a synonym of "extinguished" from his metaphor of "flame".', NULL, NULL, 'CASE', 'English', 'Nelson Mandela: Long Walk to Freedom', 4, '(i) People must learn to hate, and if they can learn hate, they can be taught to love because love matches human nature closely. (ii) Glimmer of humanity seen for a fleeting second in one of the prison guards. (iii) Locked behind bars of prejudice and narrow-mindedness. (iv) Put out / quenched.', '4 × 1M = 4M', 'Context: In prison, when pushed to their physical limits, Mandela noticed a tiny spark of compassion on a guard''s face that kept him convinced human goodness is a flame that can be hidden but never extinguished.', '(i) People must learn to hate, and if they can learn hate, they can be taught to love because love matches human nature closely. (ii) Glimmer of humanity seen for a fleeting second in one of the prison guards. (iii) Locked behind bars of prejudice and narrow-mindedness. (iv) Put out / quenched.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000017', 'Discuss Mandela''s tribute to earlier South African freedom fighters like Oliver Tambo, Walter Sisulu, Chief Luthuli, and Bram Fischer.', NULL, NULL, 'CASE', 'English', 'Nelson Mandela: Long Walk to Freedom', 4, 'Mandela humbly calls himself merely the sum of all those African patriots who went before him. Their extraordinary courage, suffering, and sacrifice created heights of character out of brutal oppression — proving a country''s greatest wealth is its people, purer than diamonds.', 'Humility & lineage (2M) + "Purer than diamonds" insight (2M)', NULL, 'Mandela humbly calls himself merely the sum of all those African patriots who went before him. Their extraordinary courage, suffering, and sacrifice created heights of character out of brutal oppression — proving a country''s greatest wealth is its people, purer than diamonds.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000018', 'Compare Nelson Mandela''s philosophy of courage, love, and non-retaliation with Mahatma Gandhi''s Satyagraha ideals in an analytical speech of 120 words.', NULL, NULL, 'LA', 'English', 'Nelson Mandela: Long Walk to Freedom', 5, 'Structured speech: Both leaders transformed victims of colonial/racial oppression without descending into vengeful hatred. Mandela conquered fear rather than denying it, argued that oppressors too need liberation from prejudice, and sought a rainbow nation uniting former rivals — echoing Gandhian truth, moral endurance, and universal human dignity.', 'Greeting & focus (1M) + Thematic parallels (3M) + Closing message (1M)', NULL, 'Structured speech: Both leaders transformed victims of colonial/racial oppression without descending into vengeful hatred. Mandela conquered fear rather than denying it, argued that oppressors too need liberation from prejudice, and sought a rainbow nation uniting former rivals — echoing Gandhian truth, moral endurance, and universal human dignity.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000019', 'Why was the young seagull afraid to take his first flight from the ledge?', '{"A":"His wings were broken","B":"He feared his wings would never support him over the vast green sea below","C":"His mother forbade him","D":"It was snowing"}'::jsonb, 'B', 'MCQ', 'English', 'Two Stories about Flying & Anne Frank', 1, 'Desperate fear that his wings would not hold him.', NULL, NULL, 'Desperate fear that his wings would not hold him.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000001a', 'What forced the starving young seagull to finally dive off the ledge?', '{"A":"A gust of wind","B":"Maddened by hunger, he dived at a piece of fish held in his mother''s beak","C":"His brothers pushed him","D":"A loud thunderclap"}'::jsonb, 'B', 'MCQ', 'English', 'Two Stories about Flying & Anne Frank', 1, 'His mother halted mid-air with fish, triggering his hunger dive.', NULL, NULL, 'His mother halted mid-air with fish, triggering his hunger dive.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000001b', 'In "The Black Aeroplane", why did the narrator NOT turn back toward Paris when facing huge storm clouds?', '{"A":"Radio was already broken","B":"He wanted to reach England in time for a big English breakfast with family","C":"He loved storms","D":"His engine locked forward"}'::jsonb, 'B', 'MCQ', 'English', 'Two Stories about Flying & Anne Frank', 1, 'Strong desire to reach home for English breakfast clouded caution.', NULL, NULL, 'Strong desire to reach home for English breakfast clouded caution.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000001c', 'What shocked the narrator when he asked the woman at the control centre about the other pilot?', '{"A":"She said he landed earlier","B":"She said no other aeroplane was flying that stormy night and none showed on radar","C":"She handed him a medal","D":"She blamed the storm"}'::jsonb, 'B', 'MCQ', 'English', 'Two Stories about Flying & Anne Frank', 1, 'Only his Dakota appeared on radar — deepening the mystery.', NULL, NULL, 'Only his Dakota appeared on radar — deepening the mystery.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000001d', 'Why did Anne Frank decide to keep a diary and name it "Kitty"?', '{"A":"She disliked school","B":"\"Paper has more patience than people\" and she wanted a true confidante","C":"Teacher ordered it","D":"She wanted to win a prize"}'::jsonb, 'B', 'MCQ', 'English', 'Two Stories about Flying & Anne Frank', 1, 'She lacked a close confiding friend despite loving family.', NULL, NULL, 'She lacked a close confiding friend despite loving family.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000001e', 'What essay topic did Mr. Keesing first assign Anne as punishment for talking in class?', '{"A":"History of Holland","B":"\"A Chatterbox\"","C":"World War II","D":"Geometry Theorems"}'::jsonb, 'B', 'MCQ', 'English', 'Two Stories about Flying & Anne Frank', 1, 'Followed by "An Incorrigible Chatterbox" and "Quack, Quack, Quack, Said Mistress Chatterbox".', NULL, NULL, 'Followed by "An Incorrigible Chatterbox" and "Quack, Quack, Quack, Said Mistress Chatterbox".', 'EASY', true),
        ('10041111-0000-4000-8000-00000000001f', 'How did Anne Frank humorously justify her habit of talking in her first essay "A Chatterbox"?', NULL, NULL, 'VSA', 'English', 'Two Stories about Flying & Anne Frank', 2, 'She argued talking is a student''s trait and she inherited it from her mother — one cannot do much about inherited traits, making Mr. Keesing laugh.', 'Student trait + inherited from mother (2M)', NULL, 'She argued talking is a student''s trait and she inherited it from her mother — one cannot do much about inherited traits, making Mr. Keesing laugh.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000020', 'Describe the moment the young seagull realised he was actually flying.', NULL, NULL, 'VSA', 'English', 'Two Stories about Flying & Anne Frank', 2, 'After a brief terror when his heart stood still, his wings spread outward automatically, wind rushed against his breast feathers, and he soared smoothly without falling headlong.', 'Initial terror -> Wings spread -> Soaring joy (2M)', NULL, 'After a brief terror when his heart stood still, his wings spread outward automatically, wind rushed against his breast feathers, and he soared smoothly without falling headlong.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000021', 'List the instruments that failed inside the old Dakota aeroplane inside the storm clouds.', NULL, NULL, 'VSA', 'English', 'Two Stories about Flying & Anne Frank', 2, 'The compass spun dead round and round, other dashboard instruments went dead, and the radio lost contact with Paris Control.', 'Compass + Instruments + Radio (2M)', NULL, 'The compass spun dead round and round, other dashboard instruments went dead, and the radio lost contact with Paris Control.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000022', '(i) How did Anne outwit Mr. Keesing on the third assignment? (ii) What poetic fable did she compose with friend Sanne? (iii) How did Mr. Keesing react afterwards? (iv) What insight does this reveal about Anne''s personality?', NULL, NULL, 'CASE', 'English', 'Two Stories about Flying & Anne Frank', 4, '(i) Turned his attempted joke back on him in verse. (ii) Three baby ducklings bitten to death by their father swan because they quacked too much. (iii) Read the poem aloud appreciatively and allowed Anne to talk in class. (iv) Sharp wit, literary creativity, and resilience.', '4 × 1M = 4M', 'Context: Tired of being ridiculed for talking during maths periods, Anne decided to collaborate with her friend Sanne to write her third essay completely in verse.', '(i) Turned his attempted joke back on him in verse. (ii) Three baby ducklings bitten to death by their father swan because they quacked too much. (iii) Read the poem aloud appreciatively and allowed Anne to talk in class. (iv) Sharp wit, literary creativity, and resilience.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000023', 'Comment on the parenting strategy in "His First Flight" vs the mysterious black aeroplane''s rescue in "The Black Aeroplane".', NULL, NULL, 'CASE', 'English', 'Two Stories about Flying & Anne Frank', 4, 'In "His First Flight", parents use tough love — withholding food until hunger compels self-reliance — proving fear dissolves upon action. In "The Black Aeroplane", a pilot risking disaster receives inexplicable guidance ("Follow me") like an inner guardian intuition when instruments fail.', '2M per story contrast', NULL, 'In "His First Flight", parents use tough love — withholding food until hunger compels self-reliance — proving fear dissolves upon action. In "The Black Aeroplane", a pilot risking disaster receives inexplicable guidance ("Follow me") like an inner guardian intuition when instruments fail.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000024', '"Fear exists mostly in the mind until we take the leap." Justify this statement with close reference to the young seagull''s first flight and how Anne Frank overcame isolation through writing.', NULL, NULL, 'LA', 'English', 'Two Stories about Flying & Anne Frank', 5, 'Synthesise both characters: Young seagull watched siblings fly yet remained paralysed on the brink until hunger forced his plunge; within seconds, self-doubt turned into effortless gliding. Similarly, Anne overcame quiet loneliness under growing Nazi restrictions by creating Kitty, converting anxiety into humorous observation and enduring courage.', 'Seagull arc (2.5M) + Anne''s courage & conclusion (2.5M)', NULL, 'Synthesise both characters: Young seagull watched siblings fly yet remained paralysed on the brink until hunger forced his plunge; within seconds, self-doubt turned into effortless gliding. Similarly, Anne overcame quiet loneliness under growing Nazi restrictions by creating Kitty, converting anxiety into humorous observation and enduring courage.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000025', 'What were the traditional bakers of Goa known as?', '{"A":"Kabai","B":"Pader","C":"Bol","D":"Bolinhas"}'::jsonb, 'B', 'MCQ', 'English', 'Glimpses of India & Mijbil the Otter', 1, 'Goan bakers are still called "pader" carrying bamboo thudding staffs.', NULL, NULL, 'Goan bakers are still called "pader" carrying bamboo thudding staffs.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000026', 'Coorg (Kodagu), Karnataka''s smallest district, is famous for:', '{"A":"Coal mines","B":"Evergreen rainforests, spices, coffee plantations, and martial people","C":"Desert dunes","D":"Tea plantations only"}'::jsonb, 'B', 'MCQ', 'English', 'Glimpses of India & Mijbil the Otter', 1, 'Home to coffee estates, martial Kodavus, and Kaveri river source.', NULL, NULL, 'Home to coffee estates, martial Kodavus, and Kaveri river source.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000027', 'Which martial Indian regiment is one of the most decorated in the Indian Army and hails from Coorg?', '{"A":"Gorkha Rifles","B":"Coorg Regiment","C":"Maratha Light Infantry","D":"Rajput Regiment"}'::jsonb, 'B', 'MCQ', 'English', 'Glimpses of India & Mijbil the Otter', 1, 'Kodavus are even permitted to carry firearms without a licence.', NULL, NULL, 'Kodavus are even permitted to carry firearms without a licence.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000028', 'Which legend explains how tea leaves were discovered in China?', '{"A":"A merchant spilled milk","B":"Tea leaves from twigs burning under an emperor''s boiling water pot fell in, giving delicious flavour","C":"Monks brewed grass","D":"Fishermen found floating leaves"}'::jsonb, 'B', 'MCQ', 'English', 'Glimpses of India & Mijbil the Otter', 1, 'Chinese Emperor legend + Indian Bodhidharma eyelid legend.', NULL, NULL, 'Chinese Emperor legend + Indian Bodhidharma eyelid legend.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000029', 'How did Gavin Maxwell acquire Mijbil the otter?', '{"A":"From London Zoo","B":"Two Arabs brought Mijbil in a sack from the Tigris marshes in Basra, Iraq","C":"Found in Scotland river","D":"From a circus"}'::jsonb, 'B', 'MCQ', 'English', 'Glimpses of India & Mijbil the Otter', 1, 'A previously unknown race named Lutrogale perspicillata maxwelli.', NULL, NULL, 'A previously unknown race named Lutrogale perspicillata maxwelli.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000002a', 'What curious hobby did Mijbil invent inside the London flat?', '{"A":"Climbing curtains","B":"Juggling marbles on his belly and rolling a ping-pong ball down a sloped broken suitcase","C":"Turning off lamps","D":"Opening jars"}'::jsonb, 'B', 'MCQ', 'English', 'Glimpses of India & Mijbil the Otter', 1, 'Dribbling a ping-pong ball down the damaged suitcase lid for half an hour.', NULL, NULL, 'Dribbling a ping-pong ball down the damaged suitcase lid for half an hour.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000002b', 'Why did Goan children eagerly wake up to the "jhang, jhang" sound of the pader''s bamboo?', NULL, NULL, 'VSA', 'English', 'Glimpses of India & Mijbil the Otter', 2, 'Because he carried not only loaves for elders, but sweet bread-bangles (kankon) specially chosen by children with longing.', 'Bamboo thud (1M) + Bread-bangles attraction (1M)', NULL, 'Because he carried not only loaves for elders, but sweet bread-bangles (kankon) specially chosen by children with longing.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000002c', 'State the two popular theories regarding the ancestral origin of the Kodavu people of Coorg.', NULL, NULL, 'VSA', 'English', 'Glimpses of India & Mijbil the Otter', 2, 'Greek descent (a section of Alexander''s army settled south when return became impractical) and Arab descent (resembled in their long black waist-belted coat, kuppia, similar to kuffia).', 'Greek (1M) + Arab/kuppia (1M)', NULL, 'Greek descent (a section of Alexander''s army settled south when return became impractical) and Arab descent (resembled in their long black waist-belted coat, kuppia, similar to kuffia).', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000002d', 'Why was Rajvir so excited during the train ride to Dhekiabari Tea Estate while Pranjol stayed buried in his detective book?', NULL, NULL, 'VSA', 'English', 'Glimpses of India & Mijbil the Otter', 2, 'Pranjol had grown up on an Assam plantation, whereas city-boy Rajvir had never seen vast green seas of manicured tea bushes against misty wooded hills.', 'Familiarity vs First-time wonder (2M)', NULL, 'Pranjol had grown up on an Assam plantation, whereas city-boy Rajvir had never seen vast green seas of manicured tea bushes against misty wooded hills.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000002e', '(i) What terrible habit of Mijbil emerged during air transport prep? (ii) Why did Maxwell rush desperately to the airport in an open car? (iii) How did the air hostess help Maxwell during the flight? (iv) How did Londoners mistake Mijbil on walks?', NULL, NULL, 'CASE', 'English', 'Glimpses of India & Mijbil the Otter', 4, '(i) Shredding the zinc box lining until he bled out of fear/frustration. (ii) Cleaning box & bandaging Mijbil left barely 10 mins for flight. (iii) Kept parcelled box safely on lap and advised keeping Mijbil on knee, helping catch him kindly. (iv) Guessed baby seal, squirrel, walrus, hippo, beaver, bear cub, even brontosaur!', '4 × 1M = 4M', 'Context: Transporting an otter from Basra to London in an 18-inch square box tested Gavin Maxwell''s patience and revealed Mijbil''s intelligent, playful temperament.', '(i) Shredding the zinc box lining until he bled out of fear/frustration. (ii) Cleaning box & bandaging Mijbil left barely 10 mins for flight. (iii) Kept parcelled box safely on lap and advised keeping Mijbil on knee, helping catch him kindly. (iv) Guessed baby seal, squirrel, walrus, hippo, beaver, bear cub, even brontosaur!', 'HARD', true),
        ('10041111-0000-4000-8000-00000000002f', 'Show how bread baking remains woven into Goan festivals, engagements, and weddings even today.', NULL, NULL, 'CASE', 'English', 'Glimpses of India & Mijbil the Otter', 4, 'Marriage gifts are meaningless without sweet bread "bol"; village feasts demand sandwiches; cakes and bolinhas are essential for Christmas and other festivals — ensuring the baker''s furnace stays ever-essential.', '3 traditional occasions (3M) + Ongoing relevance (1M)', NULL, 'Marriage gifts are meaningless without sweet bread "bol"; village feasts demand sandwiches; cakes and bolinhas are essential for Christmas and other festivals — ensuring the baker''s furnace stays ever-essential.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000030', 'Write a vivid travelogue feature (120 words) highlighting India''s regional diversity through Goan heritage baking, Coorg''s coffee-scented hills, and Assam''s lush tea gardens.', NULL, NULL, 'LA', 'English', 'Glimpses of India & Mijbil the Otter', 5, 'Weave cultural sensory details: aroma of morning wood-fired Goan loaves & pader''s bamboo, Coorg''s mist-wrapped coffee trails, Kaveri mahseer fish & proud Kodavu hospitality, and Assam''s second-flush tea pluckers carrying bamboo baskets — showing unity in rich geographical culture.', 'All 3 regions covered accurately (3.5M) + Vivid travelogue style (1.5M)', NULL, 'Weave cultural sensory details: aroma of morning wood-fired Goan loaves & pader''s bamboo, Coorg''s mist-wrapped coffee trails, Kaveri mahseer fish & proud Kodavu hospitality, and Assam''s second-flush tea pluckers carrying bamboo baskets — showing unity in rich geographical culture.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000031', 'What was Valli''s favourite pastime while standing in her front doorway?', '{"A":"Counting passing bicycles","B":"Watching street activity, especially the hourly town bus","C":"Playing hopscotch","D":"Reading comics"}'::jsonb, 'B', 'MCQ', 'English', 'Madam Rides the Bus, Benares & The Proposal', 1, 'The hourly bus filled her with an overwhelming desire to ride.', NULL, NULL, 'The hourly bus filled her with an overwhelming desire to ride.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000032', 'What suddenly dampened Valli''s cheerful return bus journey?', '{"A":"Rain started","B":"She saw the lively young cow she had laughed at lying dead by the roadside","C":"She lost her 30 paise","D":"The conductor scolded her"}'::jsonb, 'B', 'MCQ', 'English', 'Madam Rides the Bus, Benares & The Proposal', 1, 'Haunting confrontation with mortality turned her joyful trip sober.', NULL, NULL, 'Haunting confrontation with mortality turned her joyful trip sober.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000033', 'Where did Siddhartha Gautama attain enlightenment, naming the tree Bodhi Tree?', '{"A":"Kapilavastu","B":"Bodh Gaya (under a peepal tree)","C":"Sarnath","D":"Benares"}'::jsonb, 'B', 'MCQ', 'English', 'Madam Rides the Bus, Benares & The Proposal', 1, 'After 7 days under the peepal tree at Bodh Gaya, he became the Buddha.', NULL, NULL, 'After 7 days under the peepal tree at Bodh Gaya, he became the Buddha.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000034', 'Why could Kisa Gotami NOT find a mustard seed from a house untouched by death?', '{"A":"Mustard was scarce","B":"Death is common and inevitable in every household","C":"Doors were locked","D":"People refused charity"}'::jsonb, 'B', 'MCQ', 'English', 'Madam Rides the Bus, Benares & The Proposal', 1, 'Buddha helped her realise mortality is universal.', NULL, NULL, 'Buddha helped her realise mortality is universal.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000035', 'In Anton Chekhov''s one-act play "The Proposal", what two absurd topics trigger fierce quarrels between Lomov and Natalya?', '{"A":"Dowry and Wedding cake","B":"Oxen Meadows ownership and superiority of their hunting dogs (Guess vs Squeezer)","C":"Weather and Farm taxes","D":"House paint and Music"}'::jsonb, 'B', 'MCQ', 'English', 'Madam Rides the Bus, Benares & The Proposal', 1, 'Petty pride eclipses their marriage proposal twice.', NULL, NULL, 'Petty pride eclipses their marriage proposal twice.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000036', 'Why did Lomov actually visit Chubukov''s estate dressed in formal evening jacket and white gloves?', '{"A":"To pay rent","B":"To propose marriage to Chubukov''s daughter Natalya","C":"To buy Oxen Meadows","D":"To borrow a horse"}'::jsonb, 'B', 'MCQ', 'English', 'Madam Rides the Bus, Benares & The Proposal', 1, 'He sought Natalya''s hand for practical domestic security despite nervousness.', NULL, NULL, 'He sought Natalya''s hand for practical domestic security despite nervousness.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000037', 'How did eight-year-old Valli meticulously plan and save for her first bus ride?', NULL, NULL, 'VSA', 'English', 'Madam Rides the Bus, Benares & The Proposal', 2, 'She listened carefully to regular riders'' conversations about distance (6 miles), time (45 mins), and fare (30 paise one way), resisted buying peppermints/toys/merry-go-round rides, and saved every stray coin up to 60 paise.', 'Information gathering (1M) + Disciplined saving (1M)', NULL, 'She listened carefully to regular riders'' conversations about distance (6 miles), time (45 mins), and fare (30 paise one way), resisted buying peppermints/toys/merry-go-round rides, and saved every stray coin up to 60 paise.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000038', 'What metaphor did Gautama Buddha use in his Benares Sermon to explain human mortality?', NULL, NULL, 'VSA', 'English', 'Madam Rides the Bus, Benares & The Proposal', 2, 'Like ripe fruits in constant danger of falling, or earthen vessels made by a potter eventually ending in being broken, mortal life is brief, troubled, and inevitably bound with death.', 'Ripe fruits / Earthen vessels metaphors (2M)', NULL, 'Like ripe fruits in constant danger of falling, or earthen vessels made by a potter eventually ending in being broken, mortal life is brief, troubled, and inevitably bound with death.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000039', 'How does Chekhov use farce and physical ailments (palpitations, numb leg) in Lomov''s character?', NULL, NULL, 'VSA', 'English', 'Madam Rides the Bus, Benares & The Proposal', 2, 'Lomov''s comic hypochondria — twitching eye, racing pulse, fainting mid-argument — satirises aristocratic marriage alliances driven by land greed rather than affection.', 'Comic satire explanation (2M)', NULL, 'Lomov''s comic hypochondria — twitching eye, racing pulse, fainting mid-argument — satirises aristocratic marriage alliances driven by land greed rather than affection.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000003a', '(i) Compare Kisa Gotami''s state of mind before and after her door-to-door search. (ii) What does "flickering and extinguished lights of the city" symbolise to her? (iii) How does Valli''s dead-cow sight parallel Kisa Gotami''s lesson? (iv) Give a synonym of "lamentation".', NULL, NULL, 'CASE', 'English', 'Madam Rides the Bus, Benares & The Proposal', 4, '(i) Selfish, blind grief -> calm acceptance of universal mortality. (ii) Individual lives shining briefly before vanishing into darkness. (iii) Both encounter death stripping away illusions, sparking sudden maturity. (iv) Grief / Mourning / Wailing.', '4 × 1M = 4M', 'Context: Exhausted at twilight along the roadside, Kisa Gotami watches city lights blink on and flicker out one by one while grasping why Buddha asked for mustard seeds from a house that never knew death.', '(i) Selfish, blind grief -> calm acceptance of universal mortality. (ii) Individual lives shining briefly before vanishing into darkness. (iii) Both encounter death stripping away illusions, sparking sudden maturity. (iv) Grief / Mourning / Wailing.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000003b', 'Evaluate the bus conductor''s attitude toward Valli throughout her independent journey.', NULL, NULL, 'CASE', 'English', 'Madam Rides the Bus, Benares & The Proposal', 4, 'The jolly conductor plays along affectionately, calling her "Madam", offering a seat, teasing her independence gently, warning her safely not to step out alone, and respecting her pride by letting her pay her full 30-paise fare.', '4 specific supportive behaviours (4M)', NULL, 'The jolly conductor plays along affectionately, calling her "Madam", offering a seat, teasing her independence gently, warning her safely not to step out alone, and respecting her pride by letting her pay her full 30-paise fare.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000003c', 'Contrast how maturity arrives through quiet observation in "Madam Rides the Bus" and philosophical awakening in "The Sermon at Benares" vs comical immaturity in "The Proposal".', NULL, NULL, 'LA', 'English', 'Madam Rides the Bus, Benares & The Proposal', 5, 'Valli and Kisa Gotami grow through confronting mortality (roadside dead cow, mustard seed lesson), cultivating empathy and wisdom. Conversely, Chekhov''s Lomov, Natalya, and Chubukov remain trapped in comical pettiness — shouting over 5-dessiatin meadows and hunting dogs even after getting engaged — showing greed blinds people to what truly matters.', 'Valli & Kisa growth (3M) + Chekhov farce contrast (2M)', NULL, 'Valli and Kisa Gotami grow through confronting mortality (roadside dead cow, mustard seed lesson), cultivating empathy and wisdom. Conversely, Chekhov''s Lomov, Natalya, and Chubukov remain trapped in comical pettiness — shouting over 5-dessiatin meadows and hunting dogs even after getting engaged — showing greed blinds people to what truly matters.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000003d', 'In Robert Frost''s "Dust of Snow", what two natural elements lift the poet''s gloomy mood?', '{"A":"Rose and Nightingale","B":"A crow and a hemlock tree","C":"Oak tree and Pigeon","D":"Willow and Rain"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 1, 'Usually gloomy symbols — crow and poisonous hemlock — bring unexpected joy.', NULL, NULL, 'Usually gloomy symbols — crow and poisonous hemlock — bring unexpected joy.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000003e', 'In "Fire and Ice", what human emotions do "fire" and "ice" symbolise respectively?', '{"A":"Anger and Laziness","B":"Desire/Greed and Hatred/Indifference","C":"Love and Joy","D":"Pride and Fear"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 1, 'Unchecked desire burns like fire; cold hatred destroys like ice.', NULL, NULL, 'Unchecked desire burns like fire; cold hatred destroys like ice.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000003f', 'In "A Tiger in the Zoo", where should the tiger ideally be lurking instead of pacing a concrete cell?', '{"A":"Behind circus rings","B":"In shadow, sliding through long grass near the water hole for plump deer","C":"Inside museum gardens","D":"Near village markets"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 1, 'Natural jungle habitat at the edge of the village/water hole.', NULL, NULL, 'Natural jungle habitat at the edge of the village/water hole.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000040', 'In "The Ball Poem", why does John Berryman choose NOT to intrude or buy the boy another ball?', '{"A":"Balls are expensive","B":"The boy must learn the \"epistemology of loss\" and stand up in a world of possessions","C":"The store was closed","D":"He forgot money"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 1, 'First real grief teaches emotional resilience.', NULL, NULL, 'First real grief teaches emotional resilience.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000041', 'Who were Belinda''s four pets in "The Tale of Custard the Dragon"?', '{"A":"Cat, Dog, Parrot, Snake","B":"Ink (black kitten), Blink (grey mouse), Mustard (yellow dog), Custard (cowardly dragon)","C":"Rabbit, Fox, Owl, Dragon","D":"Lion, Mouse, Dog, Bird"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 1, 'All mocked Custard until a pirate broke in.', NULL, NULL, 'All mocked Custard until a pirate broke in.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000042', 'What literary device is prominent when "Amanda!" contrasts parental nagging with Daydreaming ("I am an orphan... I am Rapunzel")?', '{"A":"Onomatopoeia","B":"Allusion and Juxtaposition/Contrast","C":"Oxymoron","D":"Pun"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 1, 'Mermaid and Rapunzel allusions contrast sharply with nagging instructions.', NULL, NULL, 'Mermaid and Rapunzel allusions contrast sharply with nagging instructions.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000043', 'How does Robert Frost use irony and contrast in "Dust of Snow" ("saved some part of a day I had rued")?', NULL, NULL, 'VSA', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 2, 'Negative omens (winter chill, black crow, poisonous hemlock) paradoxically cure his depressive regret, proving small unexpected moments in nature carry restorative power.', 'Symbol inversion (1M) + Mood change (1M)', NULL, 'Negative omens (winter chill, black crow, poisonous hemlock) paradoxically cure his depressive regret, proving small unexpected moments in nature carry restorative power.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000044', 'Why does the caged tiger in Leslie Norris''s poem ignore visitors and stare at brilliant stars?', NULL, NULL, 'VSA', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 2, 'Locked behind concrete bars, his quiet rage finds no freedom by day; staring at distant free stars at night reflects longing for boundless wild skies.', 'Quiet rage & helplessness (1M) + Longing for freedom (1M)', NULL, 'Locked behind concrete bars, his quiet rage finds no freedom by day; staring at distant free stars at night reflects longing for boundless wild skies.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000045', 'In "How to Tell Wild Animals", how does Carolyn Wells create humour while describing dangerous beasts?', NULL, NULL, 'VSA', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 2, 'She jokingly advises identifying an Asian Lion as it roars while you are dying, a Bengal Tiger as it eats you, or a Bear by its deadly "hug" — blending terror with playful exaggeration.', '2 comic examples (2M)', NULL, 'She jokingly advises identifying an Asian Lion as it roars while you are dying, a Bengal Tiger as it eats you, or a Bear by its deadly "hug" — blending terror with playful exaggeration.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000046', '(i) What does "a world of possessions" mean in "The Ball Poem"? (ii) Why does "no one buys a ball back"? (iii) What is "epistemology of loss"? (iv) Explain the transferred epithet "desperate eyes".', NULL, NULL, 'CASE', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 4, '(i) Materialistic world obsessed with owning things that inevitably break or vanish. (ii) Money is external; it cannot replace sentimental childhood memories or lost innocence. (iii) Knowing and accepting the nature of loss. (iv) The boy''s eyes reflect his own inner desperation.', '4 × 1M = 4M', 'Context: Watching his cherished ball bounce merrily down the street into harbour waters, a young boy stands rigid, trembling, and staring helplessly as the poet observes silently.', '(i) Materialistic world obsessed with owning things that inevitably break or vanish. (ii) Money is external; it cannot replace sentimental childhood memories or lost innocence. (iii) Knowing and accepting the nature of loss. (iv) The boy''s eyes reflect his own inner desperation.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000047', 'Compare the true courage of Custard the dragon with the empty boasting of Ink, Blink, and Mustard.', NULL, NULL, 'CASE', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 4, 'While Ink, Blink, and Mustard brag of chasing lions and tigers, all three flee in terror when an armed pirate climbs through the window. Only Custard — who humbly cried for a safe cage — snorts fire, clashes his tail like irons, and gobbles the pirate whole, proving action outweighs boasting.', 'Boasters'' cowardice (2M) + Custard''s bravery (2M)', NULL, 'While Ink, Blink, and Mustard brag of chasing lions and tigers, all three flee in terror when an armed pirate climbs through the window. Only Custard — who humbly cried for a safe cage — snorts fire, clashes his tail like irons, and gobbles the pirate whole, proving action outweighs boasting.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000048', 'Critically examine how childhood freedom and emotional sensitivity are explored in "Amanda!" and "The Trees" (Adrienne Rich).', NULL, NULL, 'LA', 'English', 'Poetry: Frost, Norris, Berryman, Ogden Nash', 5, 'In "Amanda!", constant adult policing ("Don''t bite your nails... Did you finish your homework?") suffocates a child''s spirit, driving her into silent escapist fantasies as mermaid, orphan, and Rapunzel. In "The Trees", roots, leaves, and boughs straining against decorative indoor glass mirror captive voices breaking out toward the open forest — celebrating liberation against confinement.', 'Amanda''s suffocation & escapes (2.5M) + The Trees liberation symbolism (2.5M)', NULL, 'In "Amanda!", constant adult policing ("Don''t bite your nails... Did you finish your homework?") suffocates a child''s spirit, driving her into silent escapist fantasies as mermaid, orphan, and Rapunzel. In "The Trees", roots, leaves, and boughs straining against decorative indoor glass mirror captive voices breaking out toward the open forest — celebrating liberation against confinement.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000049', 'In Carl Sandburg''s "Fog", what animal is the fog compared to via an extended metaphor?', '{"A":"A silent owl","B":"A little cat coming on silent feet, sitting on haunches, then moving on","C":"A prowling wolf","D":"A sleeping bear"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 1, 'Extended metaphor compares quiet unpredictable fog to a cat.', NULL, NULL, 'Extended metaphor compares quiet unpredictable fog to a cat.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000004a', 'Why are the trees inside the house breaking glass and moving out at night in Adrienne Rich''s poem?', '{"A":"Too much water","B":"They belong outdoors in the empty forest rather than trapped in an artificial house","C":"They hate sunlight","D":"A storm blew them"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 1, 'Symbolises liberation of nature and suppressed women from domestic walls.', NULL, NULL, 'Symbolises liberation of nature and suppressed women from domestic walls.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000004b', 'What does Anne Gregory declare she can do to her yellow hair to test whether young men love her for herself alone?', '{"A":"Cut it short","B":"Dye it brown, black, or carrot colour","C":"Hide it in a hat","D":"Wash it in river"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 1, 'Proves outer beauty can be changed at will.', NULL, NULL, 'Proves outer beauty can be changed at will.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000004c', 'According to the "old religious man" quoted by W.B. Yeats in "For Anne Gregory", who alone can love Anne for herself alone and not her yellow hair?', '{"A":"Her parents","B":"Only God","C":"A poet","D":"Everyone"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 1, 'Humans judge by external appearance; only divine love sees inner soul.', NULL, NULL, 'Humans judge by external appearance; only divine love sees inner soul.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000004d', 'In "The Trees", what happens to the moon by the end of the poem?', '{"A":"It vanishes completely","B":"It breaks like a mirror whose pieces flash now in the crown of the tallest oak","C":"It turns blood red","D":"It sinks into ocean"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 1, 'Tree branches obscure the full moon like shattered mirror shards.', NULL, NULL, 'Tree branches obscure the full moon like shattered mirror shards.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000004e', 'In "Fog", what does "looking over harbour and city on silent haunches" convey?', '{"A":"Loud chaos","B":"Quiet watchful stillness before drifting away unexpectedly","C":"Destructive storm","D":"Permanent darkness"}'::jsonb, 'B', 'MCQ', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 1, 'Brief silent pause mirroring natural cycle.', NULL, NULL, 'Brief silent pause mirroring natural cycle.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000004f', 'Identify two poetic devices in Carl Sandburg''s "Fog" and explain the effect of its short free-verse length.', NULL, NULL, 'VSA', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 2, 'Extended metaphor (fog = cat) and Personification ("sits looking... moves on"). Its brief six-line free-verse structure mirrors the fleeting, quiet arrival and departure of real fog.', 'Devices (1M) + Structure effect (1M)', NULL, 'Extended metaphor (fog = cat) and Personification ("sits looking... moves on"). Its brief six-line free-verse structure mirrors the fleeting, quiet arrival and departure of real fog.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000050', 'Why does the speaker in "The Trees" barely mention the departure of the forest in her long letters?', NULL, NULL, 'VSA', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 2, 'Perhaps out of shock, awe, or quiet complicity — she watches silently at night as long-confined energy finally reclaims its rightful space.', 'Silent witness / shock insight (2M)', NULL, 'Perhaps out of shock, awe, or quiet complicity — she watches silently at night as long-confined energy finally reclaims its rightful space.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000051', 'Explain the significance of the phrase "great honey-coloured / Ramparts at your ear" in Yeats''s poem.', NULL, NULL, 'VSA', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 2, 'Metaphorically likens Anne''s thick golden locks falling beside her ears to protective castle walls ("ramparts") guarding her true inner self from shallow admirers.', 'Metaphor of ramparts/protection (2M)', NULL, 'Metaphorically likens Anne''s thick golden locks falling beside her ears to protective castle walls ("ramparts") guarding her true inner self from shallow admirers.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000052', '(i) Contrast outward appearance vs inner character in "For Anne Gregory". (ii) Why does Yeats describe young men being "thrown into despair"? (iii) What proof did the old religious man cite? (iv) How is the tone of the poem conversational?', NULL, NULL, 'CASE', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 4, '(i) Yellow hair fascinates eyes, hiding inner worth that Anne wishes were loved directly. (ii) Superficial infatuation with physical beauty overshadows genuine affection. (iii) He found a religious text declaring only God loves without superficiality. (iv) Direct dialogue between speaker and Anne.', '4 × 1M = 4M', 'Context: In W.B. Yeats''s dialogue lyric, a young woman argues she could dye her golden curls any colour so lovers might value her inner soul instead of outer charm.', '(i) Yellow hair fascinates eyes, hiding inner worth that Anne wishes were loved directly. (ii) Superficial infatuation with physical beauty overshadows genuine affection. (iii) He found a religious text declaring only God loves without superficiality. (iv) Direct dialogue between speaker and Anne.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000053', 'Trace the imagery of effort and liberation in the first two stanzas of Adrienne Rich''s "The Trees".', NULL, NULL, 'CASE', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 4, 'Roots "work all night to disengage themselves from cracks in the veranda floor"; leaves strain toward the glass; small twigs are stiff with exertion; long-cramped boughs shuffle under the roof like "newly discharged patients half-dazed" heading to clinic doors.', '4 concrete images cleanly explained (4M)', NULL, 'Roots "work all night to disengage themselves from cracks in the veranda floor"; leaves strain toward the glass; small twigs are stiff with exertion; long-cramped boughs shuffle under the roof like "newly discharged patients half-dazed" heading to clinic doors.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000054', 'Compare how nature represents quiet patience in Sandburg''s "Fog", urgent liberation in Rich''s "The Trees", and true inner beauty beyond appearances in Yeats''s "For Anne Gregory".', NULL, NULL, 'LA', 'English', 'Poetry: Fog, The Trees & For Anne Gregory', 5, 'Synthesise three distinct poetic lenses: Sandburg captures quiet mystery and transience through the minimalist cat-fog metaphor; Rich harnesses visceral physical struggle (roots, twigs, shattered glass/moon) to celebrate freeing captive nature/identity; Yeats shifts from external golden aesthetics toward spiritual depth.', 'Fog (1.5M) + The Trees (2M) + For Anne Gregory (1.5M)', NULL, 'Synthesise three distinct poetic lenses: Sandburg captures quiet mystery and transience through the minimalist cat-fog metaphor; Rich harnesses visceral physical struggle (roots, twigs, shattered glass/moon) to celebrate freeing captive nature/identity; Yeats shifts from external golden aesthetics toward spiritual depth.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000055', 'What was the real cause of Tricki''s severe illness in "A Triumph of Surgery"?', '{"A":"A rare virus","B":"Overfeeding rich treats (cream cakes, chocolates, cod-liver oil) and zero exercise by Mrs. Pumphrey","C":"Cold winter weather","D":"Poisoned food"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 1–5)', 1, 'Pampering and lack of exercise made Tricki bloated and listless.', NULL, NULL, 'Pampering and lack of exercise made Tricki bloated and listless.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000056', 'How did Dr. James Herriot cure Tricki in his clinic?', '{"A":"Expensive injections","B":"Giving him plenty of water, no food for two days, then playful rough-and-tumble exercise with other dogs","C":"Surgery","D":"Vitamin pills"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 1–5)', 1, 'Natural diet control and active play cured Tricki without medicine.', NULL, NULL, 'Natural diet control and active play cured Tricki without medicine.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000057', 'In "The Thief''s Story", why did Hari Singh return to Anil after catching and missing the Lucknow Express?', '{"A":"Police spotted him","B":"Anil''s quiet trust and promise to teach him to read whole sentences awakened his conscience","C":"The money fell off","D":"Station was closed"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 1–5)', 1, 'Desire for education and respect overtook stealing ₹600.', NULL, NULL, 'Desire for education and respect overtook stealing ₹600.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000058', 'How did secret agent Ausable outsmart armed intruder Max in "The Midnight Visitor"?', '{"A":"Used a hidden pistol","B":"Fabricated a convincing story about a non-existent balcony outside his sixth-floor window","C":"Fought hand-to-hand","D":"Called elevator guards"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 1–5)', 1, 'Presence of mind defeated Max when a waiter knocked at the door.', NULL, NULL, 'Presence of mind defeated Max when a waiter knocked at the door.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000059', 'Who turned out to be the clever thief who tricked Horace Danby at Shotover Grange?', '{"A":"The butler","B":"A poised young lady in red pretending to be the house owner''s wife","C":"Police inspector","D":"Sherry the dog"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 1–5)', 1, 'She walked off with ₹15,000 jewels while Horace left bare-hand fingerprints.', NULL, NULL, 'She walked off with ₹15,000 jewels while Horace left bare-hand fingerprints.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000005a', 'In "Footprints Without Feet", what flaw did scientist Griffin share despite his brilliance in discovering invisibility?', '{"A":"He was timid","B":"He was a lawless, vindictive man who set fire to his landlord''s house and robbed shops/clergymen","C":"He lost his notes","D":"He could not speak"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 1–5)', 1, 'Misuse of science without ethics leads to chaos.', NULL, NULL, 'Misuse of science without ethics leads to chaos.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000005b', 'Why did Mrs. Pumphrey exclaim "This is a triumph of surgery!" when picking up Tricki?', NULL, NULL, 'VSA', 'English', 'Footprints Without Feet (Units 1–5)', 2, 'Having imagined Tricki needed life-saving medical surgery, seeing him transformed into a lithe, hard-muscled dog overwhelmed her with gratitude, unaware he was cured simply by diet and play.', 'Irony of "surgery" vs real cure (2M)', NULL, 'Having imagined Tricki needed life-saving medical surgery, seeing him transformed into a lithe, hard-muscled dog overwhelmed her with gratitude, unaware he was cured simply by diet and play.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000005c', 'How did Anil quietly show Hari Singh the next morning that he knew about the night''s theft yet forgave him?', NULL, NULL, 'VSA', 'English', 'Footprints Without Feet (Units 1–5)', 2, 'Anil handed Hari a ₹50 note that was still damp from the midnight rain and calmly told him they would now start writing whole sentences — saying not a word of accusation.', 'Damp ₹50 note (1M) + Forgiveness & teaching (1M)', NULL, 'Anil handed Hari a ₹50 note that was still damp from the midnight rain and calmly told him they would now start writing whole sentences — saying not a word of accusation.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000005d', 'Why did Horace Danby carefully wear gloves while cracking safes, yet get caught for the Shotover Grange robbery?', NULL, NULL, 'VSA', 'English', 'Footprints Without Feet (Units 1–5)', 2, 'He always avoided leaving fingerprints; however, the disguised young woman tricked him into lighting her cigarette and opening the safe bare-handed on the pretext of forgetting her safe numbers.', 'Gloves habit + Bare-handed safe trick (2M)', NULL, 'He always avoided leaving fingerprints; however, the disguised young woman tricked him into lighting her cigarette and opening the safe bare-handed on the pretext of forgetting her safe numbers.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000005e', '(i) Why did Ausable call Fowler "disappointed" at the start of "The Midnight Visitor"? (ii) Who actually knocked on the hotel door? (iii) How did Max react when Ausable said it was the police? (iv) What lesson does Ausable teach about appearances vs intellect?', NULL, NULL, 'CASE', 'English', 'Footprints Without Feet (Units 1–5)', 4, '(i) Ausable looked fat, sloppy, and spoke with an American-French accent rather than looking like a glamorous movie spy. (ii) Henry the waiter bringing drinks. (iii) Panicked and jumped out the window expecting a balcony, falling to his doom. (iv) Calm quick thinking beats physical intimidation.', '4 × 1M = 4M', 'Context: Romantic young writer Fowler expected thrilling chases and mysterious beauties while shadowing secret agent Ausable, only to sit in a gloomy sixth-floor Paris hotel room until Max appeared with an automatic pistol.', '(i) Ausable looked fat, sloppy, and spoke with an American-French accent rather than looking like a glamorous movie spy. (ii) Henry the waiter bringing drinks. (iii) Panicked and jumped out the window expecting a balcony, falling to his doom. (iv) Calm quick thinking beats physical intimidation.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000005f', 'Discuss how "The Thief''s Story" proves kindness and education reform a criminal far more effectively than punishment.', NULL, NULL, 'CASE', 'English', 'Footprints Without Feet (Units 1–5)', 4, 'Hari Singh had perfected flattering employers before stealing and vanishing; Anil''s simple trust (giving him the room key) and unpaid patience in teaching him to write his name showed Hari that becoming "a really big man, a clever and respected man" far outvalued ₹600.', 'Trust & key (2M) + Education transformation (2M)', NULL, 'Hari Singh had perfected flattering employers before stealing and vanishing; Anil''s simple trust (giving him the room key) and unpaid patience in teaching him to write his name showed Hari that becoming "a really big man, a clever and respected man" far outvalued ₹600.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000060', 'Compare two uses of cleverness in this section: Ausable''s moral quick-wittedness saving lives vs Griffin''s selfish misuse of scientific invisibility.', NULL, NULL, 'LA', 'English', 'Footprints Without Feet (Units 1–5)', 5, 'Ausable uses psychological manipulation purely defensively to disarm a killer without firing a shot. In contrast, Griffin turns an extraordinary scientific breakthrough (making the human body transparent like glass) into petty arson, shop theft in Drury Lane, and attacking Mrs. Hall & Constable Jaffers — illustrating science divorced from morality destroys the scientist.', 'Ausable (2M) + Griffin ethical critique (3M)', NULL, 'Ausable uses psychological manipulation purely defensively to disarm a killer without firing a shot. In contrast, Griffin turns an extraordinary scientific breakthrough (making the human body transparent like glass) into petty arson, shop theft in Drury Lane, and attacking Mrs. Hall & Constable Jaffers — illustrating science divorced from morality destroys the scientist.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000061', 'Which childhood book opened the world of science to Richard Ebright in "The Making of a Scientist"?', '{"A":"Origin of Species","B":"The Travels of Monarch X","C":"Brief History of Time","D":"Microbe Hunters"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 6–9)', 1, 'His mother gifted him The Travels of Monarch X.', NULL, NULL, 'His mother gifted him The Travels of Monarch X.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000062', 'What crucial theory did Richard Ebright discover with roommate James R. Wong while studying monarch pupa gold spots?', '{"A":"Antibiotic synthesis","B":"How cells read the blueprint of their DNA (hormone triggers for full butterfly wing development)","C":"Solar photosynthesis","D":"Gene editing"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 6–9)', 1, 'Published in Proceedings of the National Academy of Science.', NULL, NULL, 'Published in Proceedings of the National Academy of Science.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000063', 'In "The Necklace", what ruined ten years of Matilda and M. Loisel''s lives?', '{"A":"A house fire","B":"Borrowing a ₹36,000 diamond necklace to replace a lost imitation paste necklace worth ₹500","C":"Stock crash","D":"Theft by servants"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 6–9)', 1, 'Matilda never confessed the loss to Mme Forestier and endured 10 years of debt for a ₹500 fake.', NULL, NULL, 'Matilda never confessed the loss to Mme Forestier and endured 10 years of debt for a ₹500 fake.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000064', 'Why did Bholi refuse at the last moment to marry Bishamber Nath?', '{"A":"He arrived late","B":"He greedily demanded ₹5,000 dowry after seeing her pockmarked face, showing mean cowardice","C":"Her friends stopped her","D":"She wanted money"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 6–9)', 1, 'Education gave Sulekha (Bholi) self-respect and courage to reject exploitation.', NULL, NULL, 'Education gave Sulekha (Bholi) self-respect and courage to reject exploitation.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000065', 'In "The Book That Saved the Earth", which nursery rhyme book saved Earth from Martian invasion in the 25th century?', '{"A":"Grimm''s Fairy Tales","B":"Mother Goose","C":"Aesop''s Fables","D":"Gulliver''s Travels"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 6–9)', 1, 'Think-Tank panicked misreading Humpty Dumpty as a plot against his balloon-head.', NULL, NULL, 'Think-Tank panicked misreading Humpty Dumpty as a plot against his balloon-head.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000066', 'Who was the sympathetic teacher who transformed Bholi from a stammering frightened girl into a confident young woman?', '{"A":"Her elder sister Champa","B":"Her primary school teacher who spoke kindly and lovingly","C":"Ramlal","D":"The Tehsildar"}'::jsonb, 'B', 'MCQ', 'English', 'Footprints Without Feet (Units 6–9)', 1, 'Her teacher''s patient affection awakened hope and dignity.', NULL, NULL, 'Her teacher''s patient affection awakened hope and dignity.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000067', 'List the three essential qualities Richard Ebright''s teacher Mr. Weiherer said made him a great scientist.', NULL, NULL, 'VSA', 'English', 'Footprints Without Feet (Units 6–9)', 2, 'A first-rate mind, genuine curiosity, and the will to win for the right reasons (wanting to do the best job possible rather than winning prizes alone).', 'Mind + Curiosity + Will to win (2M)', NULL, 'A first-rate mind, genuine curiosity, and the will to win for the right reasons (wanting to do the best job possible rather than winning prizes alone).', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000068', 'Why did Matilda Loisel suffer incessantly at the start of "The Necklace"?', NULL, NULL, 'VSA', 'English', 'Footprints Without Feet (Units 6–9)', 2, 'Born into a modest clerk family and married to a petty Ministry clerk, she tortured herself coveting luxurious tapestries, jewels, and aristocratic admiration far beyond her means.', 'Material discontent & vanity (2M)', NULL, 'Born into a modest clerk family and married to a petty Ministry clerk, she tortured herself coveting luxurious tapestries, jewels, and aristocratic admiration far beyond her means.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000069', 'How did Think-Tank absurdly misinterpret books inside Centerville Public Library?', NULL, NULL, 'VSA', 'English', 'Footprints Without Feet (Units 6–9)', 2, 'First he guessed they were Earth "sandwiches" (forcing Omega/Iota/Oop to bite them), then listening devices ("ear communication"), and finally eye-decoded nursery rhymes as Earth military plans.', 'Sandwiches -> Ear gadgets -> Military codes (2M)', NULL, 'First he guessed they were Earth "sandwiches" (forcing Omega/Iota/Oop to bite them), then listening devices ("ear communication"), and finally eye-decoded nursery rhymes as Earth military plans.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000006a', '(i) Compare Bholi''s father Ramlal''s priorities with Bholi''s teacher''s vision. (ii) Why had Bishamber originally agreed to marry Bholi without dowry? (iii) How does Bholi promise to look after her aging parents after refusing marriage? (iv) Explain the significance of her real name "Sulekha" at the end.', NULL, NULL, 'CASE', 'English', 'Footprints Without Feet (Units 6–9)', 4, '(i) Ramlal feared family dishonour ("no one will marry her"); teacher shaped independent intellect & dignity. (ii) Rumour of her lack of beauty/sense didn''t bother an elderly limping grocer getting a young bride. (iii) By teaching at the same village school. (iv) Throwing off "Bholi" (simpleton) and reclaiming "Sulekha" marks complete empowerment.', '4 × 1M = 4M', 'Context: Holding the garland trembling, greedy Bishamber demands 5,000 rupees to save Ramlal''s honour, prompting the once-stammering bride to fling the garland into the sacred fire with steady, fearless clarity.', '(i) Ramlal feared family dishonour ("no one will marry her"); teacher shaped independent intellect & dignity. (ii) Rumour of her lack of beauty/sense didn''t bother an elderly limping grocer getting a young bride. (iii) By teaching at the same village school. (iv) Throwing off "Bholi" (simpleton) and reclaiming "Sulekha" marks complete empowerment.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000006b', 'Explain how honesty could have saved Matilda Loisel ten years of gruelling poverty, and contrast her vanity with her husband''s quiet devotion.', NULL, NULL, 'CASE', 'English', 'Footprints Without Feet (Units 6–9)', 4, 'Had Matilda confessed losing the necklace immediately, Mme Forestier would have revealed it was paste worth 500 francs. Meanwhile, M. Loisel quietly sacrifices 18,000 francs saved for a hunting gun, borrows at ruinous interest, and works evenings copying manuscripts without blaming her.', 'Honesty lesson (2M) + Husband''s sacrifice (2M)', NULL, 'Had Matilda confessed losing the necklace immediately, Mme Forestier would have revealed it was paste worth 500 francs. Meanwhile, M. Loisel quietly sacrifices 18,000 francs saved for a hunting gun, borrows at ruinous interest, and works evenings copying manuscripts without blaming her.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000006c', 'Compare the transformative power of Education and Mentorship in Richard Ebright''s scientific triumph ("The Making of a Scientist") and Sulekha''s social stand ("Bholi").', NULL, NULL, 'LA', 'English', 'Footprints Without Feet (Units 6–9)', 5, 'Both protagonists grow under caring mentors: Ebright''s mother encouraged curiosity, bought microscopes/telescopes, and gifted The Travels of Monarch X, while Dr. Urquhart and Mr. Weiherer steered him from simply collecting to true experimental science. Similarly, Bholi''s compassionate teacher cured her stammer through warmth and literacy, turning a neglected girl into "Sulekha" who stands bravely against dowry humiliation.', 'Ebright mentorship (2.5M) + Bholi empowerment & synthesis (2.5M)', NULL, 'Both protagonists grow under caring mentors: Ebright''s mother encouraged curiosity, bought microscopes/telescopes, and gifted The Travels of Monarch X, while Dr. Urquhart and Mr. Weiherer steered him from simply collecting to true experimental science. Similarly, Bholi''s compassionate teacher cured her stammer through warmth and literacy, turning a neglected girl into "Sulekha" who stands bravely against dowry humiliation.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000006d', 'Fill in the blank: Neither the captain nor the players _____ aware of the sudden change in schedule.', '{"A":"is","B":"was","C":"were","D":"has been"}'::jsonb, 'C', 'MCQ', 'English', 'English Grammar Mastery (Integrated)', 1, 'With neither...nor, verb agrees with closer plural subject "players" -> were.', NULL, NULL, 'With neither...nor, verb agrees with closer plural subject "players" -> were.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000006e', 'Choose the correct modal: You _____ follow traffic signals strictly; otherwise heavy fines apply.', '{"A":"might","B":"must","C":"could","D":"used to"}'::jsonb, 'B', 'MCQ', 'English', 'English Grammar Mastery (Integrated)', 1, 'Strong obligation / legal rule uses "must".', NULL, NULL, 'Strong obligation / legal rule uses "must".', 'EASY', true),
        ('10041111-0000-4000-8000-00000000006f', 'Identify correct reported speech: Riya said to Aman, "Have you submitted the science project?"', '{"A":"Riya asked Aman if he has submitted the science project.","B":"Riya asked Aman if he had submitted the science project.","C":"Riya told Aman did he submit the project.","D":"Riya asked Aman that had he submitted the project."}'::jsonb, 'B', 'MCQ', 'English', 'English Grammar Mastery (Integrated)', 1, 'Present perfect ("have submitted") shifts to past perfect ("had submitted") with "if".', NULL, NULL, 'Present perfect ("have submitted") shifts to past perfect ("had submitted") with "if".', 'EASY', true),
        ('10041111-0000-4000-8000-000000000070', 'Fill in with the right tense: By the time we reached the railway platform, the Rajdhani Express _____ already _____.', '{"A":"has, left","B":"had, left","C":"was, leaving","D":"will, leave"}'::jsonb, 'B', 'MCQ', 'English', 'English Grammar Mastery (Integrated)', 1, 'Earlier past action uses Past Perfect (had left).', NULL, NULL, 'Earlier past action uses Past Perfect (had left).', 'EASY', true),
        ('10041111-0000-4000-8000-000000000071', 'Choose the correct determiner: There is _____ milk left in the jug, just enough for one cup of tea.', '{"A":"a few","B":"a little","C":"many","D":"several"}'::jsonb, 'B', 'MCQ', 'English', 'English Grammar Mastery (Integrated)', 1, 'Positive small quantity with uncountable "milk" -> "a little".', NULL, NULL, 'Positive small quantity with uncountable "milk" -> "a little".', 'EASY', true),
        ('10041111-0000-4000-8000-000000000072', 'Spot and correct the error: "Each of the twenty participants were given a certificate."', '{"A":"Error: Each -> Every","B":"Error: were -> was","C":"Error: given -> gave","D":"Error: participants -> participant"}'::jsonb, 'B', 'MCQ', 'English', 'English Grammar Mastery (Integrated)', 1, '"Each of + plural noun" takes singular verb "was".', NULL, NULL, '"Each of + plural noun" takes singular verb "was".', 'EASY', true),
        ('10041111-0000-4000-8000-000000000073', 'Edit the following error-correction lines (2 errors): "(a) Climate change have become one of the (b) biggest challenges facing humanity since decades."', NULL, NULL, 'VSA', 'English', 'English Grammar Mastery (Integrated)', 2, '(a) have -> has ("Climate change" is singular). (b) since -> for ("decades" is a duration of time).', '1M per correction × 2', NULL, '(a) have -> has ("Climate change" is singular). (b) since -> for ("decades" is a duration of time).', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000074', 'Convert into Indirect Speech: The teacher said to the students, "Do not waste time before your board examinations."', NULL, NULL, 'VSA', 'English', 'English Grammar Mastery (Integrated)', 2, 'The teacher advised (or instructed) the students not to waste time before their board examinations.', 'Reporting verb & "not to waste" (1M) + pronoun "their" (1M)', NULL, 'The teacher advised (or instructed) the students not to waste time before their board examinations.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000075', 'Complete the dialogue in reported speech:
        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('10041111-0000-4000-8000-0000000000c9', '[From Passage "Solar Microgrids Transforming Remote Himalayan Hamlets"] Which word in the passage means "spread away from a single central authority/source"?', '{"A":"Insulated","B":"Decentralised","C":"Crisp","D":"Smoky"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. "Decentralised" refers to local village-level microgrids rather than one central grid.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000ca', '[From Passage "Solar Microgrids Transforming Remote Himalayan Hamlets"] More than how many high-altitude hamlets have been electrified by these DC solar microgrids?', '{"A":"20","B":"50","C":"200","D":"3,800"}'::jsonb, 'C', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (C) is correct. Over 200 high-altitude hamlets have received electricity.', 'Correct option (C) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000cb', '[From Passage "Solar Microgrids Transforming Remote Himalayan Hamlets"] Explain why high-altitude regions like Ladakh are actually well suited for solar photovoltaic power.', NULL, NULL, 'VSA', 'English', 'Reading Comprehension', 2, 'Despite freezing temperatures, high-altitude regions above 3,800 m receive intense, crisp mountain sunlight with clear skies, allowing photovoltaic panels to operate at high efficiency.', 'Two clear passage-supported points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase neatly in your own words without exceeding 40 words. | Common Pitfall: Copying an entire paragraph verbatim.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000cc', '[From Passage "Solar Microgrids Transforming Remote Himalayan Hamlets"] State two health and livelihood benefits of replacing kerosene lamps with solar microgrids.', NULL, NULL, 'VSA', 'English', 'Reading Comprehension', 2, 'Health improves because indoor air pollution from smoky kerosene fumes is eliminated; livelihoods and education improve via extended student study hours and solar-pumped greenhouse farming.', 'Two clear passage-supported points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase neatly in your own words without exceeding 40 words. | Common Pitfall: Copying an entire paragraph verbatim.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000cd', 'Spot the error and fix: "Although he worked hard, but he could not finish the last section on time."', '{"A":"Error: worked -> works","B":"Error: but -> (remove \"but\", use comma)","C":"Error: could -> can","D":"Error: on -> at"}'::jsonb, 'B', 'MCQ', 'English', 'Grammar', 1, 'Option (B) is correct. "Although" is never followed by "but" in standard English grammar.', 'Accurate grammatical choice (B) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000ce', 'You are Kabir/Kavya of 18, Civil Lines, Jaipur. You wish to join a 4-week weekend Python & Robotics Bootcamp during winter break. Write a letter of enquiry in 100–120 words to the Director, FutureTech Academy, Jaipur asking about batch timings, fee structure, hardware kits, and certification.', NULL, NULL, 'LA', 'English', 'Writing', 5, '18, Civil Lines
