-- V470: Seed 128 Class 10 English Mock Tests (104 Real-Format 80M Papers + 24 Chapter-Wise 25M Mocks)

DO $$
DECLARE
    v_class10_id UUID;
BEGIN
    SELECT id INTO v_class10_id FROM learn_exam_types WHERE slug IN ('class-10', 'cbse-class-10') LIMIT 1;
    IF v_class10_id IS NULL THEN
        SELECT id INTO v_class10_id FROM learn_exam_types WHERE name ILIKE '%Class 10%' LIMIT 1;
    END IF;

    IF v_class10_id IS NOT NULL THEN
        DELETE FROM learn_test_questions WHERE mock_test_id IN (SELECT id FROM learn_mock_tests WHERE id::text LIKE '10040000-%');
        DELETE FROM learn_mock_tests WHERE id::text LIKE '10040000-%';

        ON CONFLICT (id) DO NOTHING;

Doctor: "Are you taking the prescribed medicine regularly?"
Patient: "Yes, I take it every morning after breakfast."
The doctor asked the patient (a) _____, to which the patient replied positively that (b) _____.', NULL, NULL, 'VSA', 'English', 'English Grammar Mastery (Integrated)', 2, '(a) if/whether he or she was taking the prescribed medicine regularly. (b) he/she took it every morning after breakfast.', '1M per blank', NULL, '(a) if/whether he or she was taking the prescribed medicine regularly. (b) he/she took it every morning after breakfast.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000076', 'Editing Passage (Find 4 errors & supply corrections):
(a) A library is a treasure house for knowledge.
(b) Reading good books develop our imagination.
(c) However, many student today prefer scrolling screens
(d) instead of visit quiet reading rooms.', NULL, NULL, 'CASE', 'English', 'English Grammar Mastery (Integrated)', 4, '(a) for -> of; (b) develop -> develops; (c) student -> students; (d) visit -> visiting.', '4 × 1M = 4M', 'Carefully proofread the given short paragraph about modern reading habits, identifying one grammatical/prepositional/tense/number error in each marked line (a)–(d).', '(a) for -> of; (b) develop -> develops; (c) student -> students; (d) visit -> visiting.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000077', 'Gap Filling Passage (4 blanks):
Solar energy (i) _____ (be) rapidly emerging as India''s cleanest power choice. If households (ii) _____ (install) rooftop panels today, they (iii) _____ (reduce) monthly electricity bills by nearly seventy percent. Every citizen (iv) _____ (should/could/need) explore green energy.', NULL, NULL, 'CASE', 'English', 'English Grammar Mastery (Integrated)', 4, '(i) is; (ii) install; (iii) will reduce (First Conditional); (iv) should.', '4 × 1M = 4M', 'Complete the climate-technology paragraph choosing grammatically accurate verb tenses, conditionals, and modals for blanks (i) to (iv).', '(i) is; (ii) install; (iii) will reduce (First Conditional); (iv) should.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000078', 'Integrated Grammar Transformation Set (5 tasks, 1M each):
1. Direct->Indirect: Rohan said, "Hurrah! Our school won the debate trophy."
2. Error fix: "One of my friend live in Dehradun."
3. Modal fill: "_____ I borrow your atlas for five minutes?" (polite request)
4. Determiner: "Hardly _____ students attended due to heavy rain." (any/some)
5. Tense: "She _____ (practise) classical music since 2021."', NULL, NULL, 'LA', 'English', 'English Grammar Mastery (Integrated)', 5, '1. Rohan exclaimed with joy that their school had won the debate trophy.
2. friend -> friends (or live -> lives; exact: "friend -> friends" AND "live -> lives").
3. May / Could.
4. any ("Hardly" is negative).
5. has been practising.', '1M each × 5 = 5M', NULL, '1. Rohan exclaimed with joy that their school had won the debate trophy.
2. friend -> friends (or live -> lives; exact: "friend -> friends" AND "live -> lives").
3. May / Could.
4. any ("Hardly" is negative).
5. has been practising.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000079', 'Which salutation/subject order is standard in a CBSE Formal Letter?', '{"A":"Subject before Salutation OR Salutation before Subject (both accepted cleanly), Date after Sender Address","B":"Salutation at the bottom","C":"No Receiver Address needed","D":"Nickname sign-off"}'::jsonb, 'A', 'MCQ', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 1, 'Sender Address -> Date -> Receiver Address -> Subject -> Salutation -> Body -> Complimentary Close.', NULL, NULL, 'Sender Address -> Date -> Receiver Address -> Subject -> Salutation -> Body -> Complimentary Close.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000007a', 'What is the prescribed word limit for a CBSE Class 10 Formal Letter & Analytical Paragraph?', '{"A":"40–50 words","B":"100–120 words","C":"300–400 words","D":"20 words"}'::jsonb, 'B', 'MCQ', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 1, 'Both writing questions carry 5 marks with 100–120 words limit.', NULL, NULL, 'Both writing questions carry 5 marks with 100–120 words limit.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000007b', 'Which complimentary close matches a Formal Letter to the Editor?', '{"A":"Yours lovingly","B":"Yours truly / Yours sincerely","C":"Best buddy","D":"Cheers"}'::jsonb, 'B', 'MCQ', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 1, 'Formal letters end with Yours truly / Yours sincerely + Name.', NULL, NULL, 'Formal letters end with Yours truly / Yours sincerely + Name.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000007c', 'In an Analytical Paragraph based on a chart/table, the writer should:', '{"A":"Write an imaginary story","B":"Summarise key trends, comparisons, highs/lows objectively without personal bias","C":"Copy every single number randomly","D":"Include rhyming couplets"}'::jsonb, 'B', 'MCQ', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 1, 'Objective data interpretation and trend comparison.', NULL, NULL, 'Objective data interpretation and trend comparison.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000007d', 'Which opening phrase best suits a Letter of Complaint about defective goods?', '{"A":"Hey there, fix this!","B":"Through the columns of your newspaper...","C":"I am writing to express grave dissatisfaction regarding the defective...","D":"Please find attached my resume..."}'::jsonb, 'C', 'MCQ', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 1, 'Specific complaint opener citing invoice/model date.', NULL, NULL, 'Specific complaint opener citing invoice/model date.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000007e', 'In a Letter to the Editor, who takes the direct civic action after reading it?', '{"A":"The newspaper editor personally fixes potholes","B":"The concerned authorities and general public awakened by publication","C":"Only the writer","D":"Foreign embassies"}'::jsonb, 'B', 'MCQ', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 1, 'Editor only publishes to draw public & official attention ("Through the columns of your esteemed daily...").', NULL, NULL, 'Editor only publishes to draw public & official attention ("Through the columns of your esteemed daily...").', 'EASY', true),
        ('10041111-0000-4000-8000-00000000007f', 'Write the complete opening header (Sender, Date, Receiver, Subject, Salutation) for a Letter to the Editor raising concern over plastic waste near city parks.', NULL, NULL, 'VSA', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 2, '24, Green Park Avenue, Lucknow

27 November 2026

The Editor
The Times of India
Lucknow

Subject: Urgent need to curb single-use plastic dumping near city parks

Sir/Madam,', 'All 5 formal layout elements cleanly formatted (2M)', NULL, '24, Green Park Avenue, Lucknow

27 November 2026

The Editor
The Times of India
Lucknow

Subject: Urgent need to curb single-use plastic dumping near city parks

Sir/Madam,', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000080', 'Give three strong transition phrases ideal for comparing data in an Analytical Paragraph.', NULL, NULL, 'VSA', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 2, '"In sharp contrast...", "Experiencing a steady upward trend...", "Significantly outperforming...", "Whereas Category A peaked at..., Category B dipped to...".', 'Any 3 accurate analytical phrases (2M)', NULL, '"In sharp contrast...", "Experiencing a steady upward trend...", "Significantly outperforming...", "Whereas Category A peaked at..., Category B dipped to...".', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000081', 'List the three compulsory parts of an Analytical Paragraph structure.', NULL, NULL, 'VSA', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 2, '(1) Introductory sentence stating what the chart/table/excerpt represents. (2) Body analysing comparative trends, percentages, peaks, and lows objectively. (3) Brief concluding takeaway summarising the overarching pattern.', 'Intro (0.5M) + Analytical body (1M) + Conclusion (0.5M)', NULL, '(1) Introductory sentence stating what the chart/table/excerpt represents. (2) Body analysing comparative trends, percentages, peaks, and lows objectively. (3) Brief concluding takeaway summarising the overarching pattern.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000082', 'Draft a concise 100-word Letter of Order on behalf of Navodaya Public School Sports Head ordering 15 cricket bats, 20 footballs, and 10 badminton nets from Apex Sports Co., citing 15% institutional discount and timely delivery.', NULL, NULL, 'CASE', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 4, 'Proper formal layout + clear itemised table/list + quality/warranty clause + delivery deadline & payment terms + Yours sincerely, Sports Coordinator.', 'Format (1M) + Itemised order & terms (2M) + Expression (1M)', 'Prompt Context: You are Aarav/Ananya, Sports Coordinator of Navodaya Public School, Jaipur, placing an urgent annual sports equipment order for the upcoming inter-school tournament.', 'Proper formal layout + clear itemised table/list + quality/warranty clause + delivery deadline & payment terms + Yours sincerely, Sports Coordinator.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000083', 'Write an Analytical Paragraph (100–120 words) interpreting this survey of teen reading preferences: Print Fiction (38%), Science Magazines (24%), E-Books (22%), Graphic Novels (16%).', NULL, NULL, 'CASE', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 4, 'Introduction explaining teen reading breakdown across four formats -> Contrast highest preference (Print Fiction 38%) against digital E-Books (22%) showing tactile print still leads -> Compare Science Magazines (24%) slightly ahead of E-Books, and Graphic Novels lowest (16%) -> Conclude that despite digital growth, traditional print books remain dominant among teenagers.', 'Trend & data coverage (2M) + Cohesive comparisons (1M) + Vocabulary/Accuracy (1M)', 'Survey Data: A national youth literacy survey of 1,000 Class 10 students recorded preferred leisure reading formats: Print Fiction 38%, Science Magazines 24%, E-Books 22%, Graphic Novels 16%.', 'Introduction explaining teen reading breakdown across four formats -> Contrast highest preference (Print Fiction 38%) against digital E-Books (22%) showing tactile print still leads -> Compare Science Magazines (24%) slightly ahead of E-Books, and Graphic Novels lowest (16%) -> Conclude that despite digital growth, traditional print books remain dominant among teenagers.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000084', 'Write a Formal Letter (100–120 words) to the Municipal Commissioner complaining about irregular garbage collection, overflowing bins, and stray-animal menace in Sector 14, Shastri Nagar, suggesting practical remedies.', NULL, NULL, 'LA', 'English', 'Creative Writing Skills (Letters & Analytical Paragraphs)', 5, 'Complete CBSE format (Sender, Date, Municipal Commissioner, Subject, Salutation) -> State specific problem (uncollected waste for 10 days causing foul stench & mosquito breeding) -> Suggest covered community bins, GPS-tracked morning vans, and source segregation -> Polite urgent closing.', 'Format (1M) + Content & practical suggestions (2M) + Accuracy & formal register (2M)', NULL, 'Complete CBSE format (Sender, Date, Municipal Commissioner, Subject, Salutation) -> State specific problem (uncollected waste for 10 days causing foul stench & mosquito breeding) -> Suggest covered community bins, GPS-tracked morning vans, and source segregation -> Polite urgent closing.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000085', 'In an unseen discursive passage, "author''s tone" refers to:', '{"A":"Font size","B":"The writer''s attitude (analytical, cautionary, optimistic, satirical) toward the subject","C":"Word count","D":"Number of paragraphs"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension (Discursive & Case-Based)', 1, 'Tone reflects the writer''s attitude conveyed via diction.', NULL, NULL, 'Tone reflects the writer''s attitude conveyed via diction.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000086', 'When asked to find a "synonym from paragraph 3", the student must:', '{"A":"Invent a new word","B":"Pick an exact word printed inside paragraph 3 matching the same part of speech and meaning","C":"Write a whole sentence","D":"Translate to Hindi"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension (Discursive & Case-Based)', 1, 'Exact word from specified paragraph & matching tense/part of speech.', NULL, NULL, 'Exact word from specified paragraph & matching tense/part of speech.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000087', 'What defines a "Case-Based Factual Passage" in CBSE Section A?', '{"A":"Only fairy tales","B":"Informational text paired with visual inputs like bar charts, pie charts, or statistical tables","C":"Blank verse poetry","D":"Grammatical error lines"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension (Discursive & Case-Based)', 1, 'Tests factual comprehension + visual/numerical inference.', NULL, NULL, 'Tests factual comprehension + visual/numerical inference.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000088', 'In Assertion-Inference reading questions, a valid inference is:', '{"A":"Pure wild guessing","B":"A logical conclusion strictly supported by evidence stated in the passage","C":"An unrelated proverb","D":"Copy-pasting the title"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension (Discursive & Case-Based)', 1, 'Inference combines stated clues logically without inventing facts.', NULL, NULL, 'Inference combines stated clues logically without inventing facts.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000089', 'Which strategy saves maximum time during CBSE 15-minute Reading Time on unseen passages?', '{"A":"Translating word-by-word","B":"Skimming passage structure first, reading the questions, then scanning targeted paragraphs for exact proof","C":"Skipping Section A completely","D":"Memorising numbers"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension (Discursive & Case-Based)', 1, 'Skimming + Question-first scanning improves precision.', NULL, NULL, 'Skimming + Question-first scanning improves precision.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000008a', 'In data-based reading questions, "marginal increase" means:', '{"A":"Massive doubling","B":"A very slight or small upward change","C":"Zero change","D":"Sharp collapse"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension (Discursive & Case-Based)', 1, '"Marginal" indicates small/slight degree.', NULL, NULL, '"Marginal" indicates small/slight degree.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000008b', 'Read & Answer (2M): "Urban wetlands act like natural sponges during cloudbursts, absorbing excess stormwater while filtering pollutants before recharging city aquifers." — Why are urban wetlands compared to natural sponges, and name two ecological benefits stated.', NULL, NULL, 'VSA', 'English', 'Reading Comprehension (Discursive & Case-Based)', 2, 'Compared to sponges because they soak up excess monsoon floodwater; benefits: flood mitigation/stormwater absorption, pollutant filtration, and groundwater aquifer recharge.', 'Analogy (1M) + Two benefits (1M)', NULL, 'Compared to sponges because they soak up excess monsoon floodwater; benefits: flood mitigation/stormwater absorption, pollutant filtration, and groundwater aquifer recharge.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000008c', 'Read & Answer (2M): "While automated translation apps remove basic travel friction, learning a second language reshapes neural pathways, delaying cognitive decline and fostering deep cultural empathy." — State two benefits of human language learning over app shortcuts.', NULL, NULL, 'VSA', 'English', 'Reading Comprehension (Discursive & Case-Based)', 2, '(1) Strengthens/reshapes neural pathways slowing cognitive aging. (2) Builds genuine cultural empathy beyond literal word swaps.', '1M each', NULL, '(1) Strengthens/reshapes neural pathways slowing cognitive aging. (2) Builds genuine cultural empathy beyond literal word swaps.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000008d', 'Read & Answer (2M): "Between 2021 and 2025, rooftop solar adoption in tier-2 Indian towns tripled from 1.2 GW to 3.6 GW after net-metering rules simplified grid feed-in." — What quantitative change occurred, and what policy triggered it?', NULL, NULL, 'VSA', 'English', 'Reading Comprehension (Discursive & Case-Based)', 2, 'Rooftop solar tripled (1.2 GW -> 3.6 GW), driven by simplified net-metering rules allowing easy grid feed-in.', '1M each', NULL, 'Rooftop solar tripled (1.2 GW -> 3.6 GW), driven by simplified net-metering rules allowing easy grid feed-in.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-00000000008e', '(i) Why did night skies vanish over mega-cities? (ii) State one biological harm of excessive artificial blue LED glare on nocturnal wildlife. (iii) Mention one human health concern linked to light pollution. (iv) Find a word in the excerpt meaning "disturbs/interrupts".', NULL, NULL, 'CASE', 'English', 'Reading Comprehension (Discursive & Case-Based)', 4, '(i) Unshielded upward-pointing billboards, streetlights, and glass towers create skyglow. (ii) Confuses migrating birds and disorients newly hatched sea turtles away from ocean moonlight. (iii) Suppresses melatonin, disrupting sleep circadian rhythms. (iv) Disrupts.', '4 × 1M = 4M', 'Artificial Light at Night (ALAN): Over 80% of the global population now lives under light-polluted skies caused by unshielded streetlights and glowing billboards. Excessive blue-rich LED glare disrupts human melatonin sleep cycles, disorients nocturnal migrating birds, and lures baby sea turtles inland away from moonlit waves.', '(i) Unshielded upward-pointing billboards, streetlights, and glass towers create skyglow. (ii) Confuses migrating birds and disorients newly hatched sea turtles away from ocean moonlight. (iii) Suppresses melatonin, disrupting sleep circadian rhythms. (iv) Disrupts.', 'HARD', true),
        ('10041111-0000-4000-8000-00000000008f', '(i) Identify two advantages of millet crops ("Shree Anna") cited in the passage. (ii) Why do millets thrive in dry semi-arid Indian belts? (iii) How does millet cultivation benefit small farmers economically? (iv) Suggest an apt concise title.', NULL, NULL, 'CASE', 'English', 'Reading Comprehension (Discursive & Case-Based)', 4, '(i) Rich in iron, fibre, calcium & low glycaemic index; drought-resilient requiring ~70% less water than paddy. (ii) Grow easily in poor soils and low rainfall. (iii) Lower irrigation/input costs reduce crop-failure risk. (iv) "Millets: Climate-Smart Nutrition".', '4 × 1M = 4M', 'Millets ("Shree Anna") such as ragi, jowar, and bajra require nearly 70% less water than paddy, thrive in dry rain-fed soils with minimal chemical inputs, and pack rich iron, fibre, and calcium—making them climate-smart nutrition for both farmers and consumers.', '(i) Rich in iron, fibre, calcium & low glycaemic index; drought-resilient requiring ~70% less water than paddy. (ii) Grow easily in poor soils and low rainfall. (iii) Lower irrigation/input costs reduce crop-failure risk. (iv) "Millets: Climate-Smart Nutrition".', 'HARD', true),
        ('10041111-0000-4000-8000-000000000090', 'Based on the passage: (a) Trace how community libraries evolved from silent book vaults into active digital-literacy hubs (2M). (b) Mention two barriers still faced by rural reading rooms (2M). (c) Give one word from the text meaning "essential" (1M).', NULL, NULL, 'LA', 'English', 'Reading Comprehension (Discursive & Case-Based)', 5, '(a) Earlier libraries merely lent physical print quietly; modern centres blend regional books with free Wi-Fi, career coding workshops, and senior reading circles. (b) Outdated book stocks and lack of trained librarians / steady power. (c) Indispensable.', '(a) 2M + (b) 2M + (c) 1M', 'Public libraries remain indispensable civic spaces. Moving beyond silent dusty shelves, modern community libraries now combine regional-language story circles, free internet access, and exam-prep corners, though many rural branches still battle outdated stock and erratic power.', '(a) Earlier libraries merely lent physical print quietly; modern centres blend regional books with free Wi-Fi, career coding workshops, and senior reading circles. (b) Outdated book stocks and lack of trained librarians / steady power. (c) Indispensable.', 'HARD', true),
        ('10041111-0000-4000-8000-000000000091', '[Read Passage: "Urban Heat Islands and Cool Roof Architecture"]
Rapidly expanding concrete cities often experience temperatures 3°C to 5°C higher than surrounding rural farmlands—a phenomenon known as the Urban Heat Island (UHI) effect. Dark asphalt roads and concrete rooftops absorb solar radiation throughout the day and release stored thermal energy slowly at night. Urban planners increasingly advocate "cool roofs" coated with high-reflectance white lime or solar-reflective polymers, alongside vertical gardens and permeable pavements. Pilot projects in Ahmedabad and Surat demonstrated that reflective roofs lowered indoor peak temperatures by nearly 3.5°C, reducing daytime air-conditioning electricity demand by up to 22%.

Why do concrete cities stay warmer at night than nearby villages?', '{"A":"Vehicles release cold exhaust","B":"Dark asphalt and concrete absorb daytime sunlight and release heat slowly at night","C":"Rural areas lack solar radiation","D":"High buildings block moonlight"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. The passage notes dark asphalt and concrete absorb solar radiation during the day and emit stored heat slowly at night.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000092', '[From Passage "Urban Heat Islands and Cool Roof Architecture"] By how much did reflective roof pilots lower peak indoor temperatures in Ahmedabad and Surat?', '{"A":"1.5°C","B":"3.5°C","C":"8°C","D":"22°C"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. Reflective roofs lowered indoor peak temperatures by nearly 3.5°C (22% refers to electricity reduction).', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000093', '[From Passage "Urban Heat Islands and Cool Roof Architecture"] Which word from the passage means "allowing liquids or gases to pass through"?', '{"A":"Reflective","B":"Permeable","C":"Thermal","D":"Solar"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. "Permeable pavements" refers to surfaces allowing water to pass through.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000094', '[From Passage "Urban Heat Islands and Cool Roof Architecture"] What energy benefit did cool roofs deliver alongside lower indoor heat?', '{"A":"Increased solar panel cost","B":"Reduced daytime AC electricity demand by up to 22%","C":"Higher asphalt durability","D":"Elimination of street lighting"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. Cool roofs reduced daytime air-conditioning electricity demand by up to 22%.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000095', '[From Passage "Urban Heat Islands and Cool Roof Architecture"] High-reflectance coatings help cool buildings primarily by:', '{"A":"Trapping infrared heat indoors","B":"Reflecting incoming solar radiation before absorption","C":"Increasing concrete thickness","D":"Generating wind currents"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. High-reflectance coatings bounce back sunlight rather than absorbing it.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000096', '[From Passage "Urban Heat Islands and Cool Roof Architecture"] The Urban Heat Island temperature gap mentioned in the passage is typically:', '{"A":"0.1°C to 0.5°C","B":"3°C to 5°C","C":"10°C to 15°C","D":"Exact 22°C"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. Cities often experience temperatures 3°C to 5°C higher than surrounding farmlands.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-000000000097', '[From Passage "Urban Heat Islands and Cool Roof Architecture"] Explain in 30–40 words how cool roofs benefit both individual households and city power grids.', NULL, NULL, 'VSA', 'English', 'Reading Comprehension', 2, 'Cool roofs keep indoor living spaces up to 3.5°C cooler naturally, lowering household cooling bills. Simultaneously, cutting air-conditioning demand by up to 22% eases peak afternoon electricity load on city power grids during heatwaves.', 'Two clear passage-supported points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase neatly in your own words without exceeding 40 words. | Common Pitfall: Copying an entire paragraph verbatim.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000098', '[From Passage "Urban Heat Islands and Cool Roof Architecture"] Apart from reflective coatings, mention two urban design features cited in the text that mitigate urban heat.', NULL, NULL, 'VSA', 'English', 'Reading Comprehension', 2, 'The passage recommends vertical gardens on building facades and permeable pavements that allow water seepage and evaporative cooling instead of trapping heat.', 'Two clear passage-supported points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase neatly in your own words without exceeding 40 words. | Common Pitfall: Copying an entire paragraph verbatim.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-000000000099', '[Read Passage: "Community Seed Banks and Climate-Resilient Millets"]
For centuries, smallholders across dryland districts preserved hundreds of indigenous millet varieties—such as finger millet (ragi), pearl millet (bajra), and foxtail millet—adapted to erratic rainfall and poor soils. When commercial monoculture expanded in the late twentieth century, many hardy local varieties vanished from farms. Over the past decade, women-led community seed banks across Odisha, Karnataka, and Telangana have catalogued, multiplied, and shared over 400 drought-tolerant seed strains without charging commercial royalties. Unlike water-intensive paddy, millets require nearly 70% less irrigation water and mature within 65 to 90 days, offering nutritional security rich in iron, dietary fibre, and calcium.

What primary factor caused many indigenous millet varieties to vanish in the late 20th century?', '{"A":"Excess rainfall","B":"Expansion of commercial monoculture","C":"Lack of calcium in soil","D":"Seed bank royalties"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. The passage states commercial monoculture expansion led to loss of hardy local varieties.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000009a', '[From Passage "Community Seed Banks and Climate-Resilient Millets"] Approximately how much less irrigation water do millets require compared to paddy?', '{"A":"25% less","B":"40% less","C":"70% less","D":"90% less"}'::jsonb, 'C', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (C) is correct. Millets require nearly 70% less irrigation water than paddy.', 'Correct option (C) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000009b', '[From Passage "Community Seed Banks and Climate-Resilient Millets"] Who primarily leads the community seed banks mentioned across Odisha, Karnataka, and Telangana?', '{"A":"Export corporations","B":"Women-led collectives","C":"Fertilizer importers","D":"Urban supermarkets"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. Women-led community seed banks catalogued and shared over 400 strains.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000009c', '[From Passage "Community Seed Banks and Climate-Resilient Millets"] Which word in the passage is synonymous with "unpredictable or irregular"?', '{"A":"Indigenous","B":"Erratic","C":"Hardy","D":"Resilient"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. "Erratic rainfall" means unpredictable or irregular rainfall.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000009d', '[From Passage "Community Seed Banks and Climate-Resilient Millets"] According to the passage, millets are rich sources of:', '{"A":"Refined sugar and starch only","B":"Iron, dietary fibre, and calcium","C":"Saturated fats","D":"Synthetic vitamins"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. The concluding sentence lists iron, dietary fibre, and calcium.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000009e', '[From Passage "Community Seed Banks and Climate-Resilient Millets"] How quickly do most indigenous millet strains mature?', '{"A":"15 to 20 days","B":"65 to 90 days","C":"180 to 210 days","D":"Over 12 months"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. Millets mature rapidly within 65 to 90 days.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-00000000009f', '[From Passage "Community Seed Banks and Climate-Resilient Millets"] Why are community seed banks considered crucial for small farmers facing climate uncertainty?', NULL, NULL, 'VSA', 'English', 'Reading Comprehension', 2, 'Community seed banks preserve 400+ drought-tolerant local strains adapted to erratic rainfall and distribute seeds without commercial royalties, enabling smallholders to grow hardy, fast-maturing crops safely.', 'Two clear passage-supported points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase neatly in your own words without exceeding 40 words. | Common Pitfall: Copying an entire paragraph verbatim.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000a0', '[From Passage "Community Seed Banks and Climate-Resilient Millets"] Compare millets and paddy based on water requirement and maturity cycle.', NULL, NULL, 'VSA', 'English', 'Reading Comprehension', 2, 'Millets require nearly 70% less irrigation water than paddy and mature within 65–90 days, making them far better suited to dryland districts with scarce rainfall.', 'Two clear passage-supported points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase neatly in your own words without exceeding 40 words. | Common Pitfall: Copying an entire paragraph verbatim.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000a1', 'Complete the sentence: "Rohan ________ for his Board Science exam since 5 a.m. this morning."', '{"A":"studies","B":"has been studying","C":"studied","D":"is studying"}'::jsonb, 'B', 'MCQ', 'English', 'Grammar', 1, 'Option (B) is correct. "Since 5 a.m." indicates an action started in the past and still continuing -> Present Perfect Continuous (has been studying).', 'Accurate grammatical choice (B) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000a2', 'Fill in the blank: "Students ________ carry their original CBSE admit card inside the examination hall; it is mandatory."', '{"A":"might","B":"could","C":"must","D":"may"}'::jsonb, 'C', 'MCQ', 'English', 'Grammar', 1, 'Option (C) is correct. "Must" expresses strict mandatory rule/obligation.', 'Accurate grammatical choice (C) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000a3', 'Choose the correct verb: "Neither the class teacher nor the two monitors ________ present at the assembly today."', '{"A":"was","B":"were","C":"is","D":"has been"}'::jsonb, 'B', 'MCQ', 'English', 'Grammar', 1, 'Option (B) is correct. With "Neither...nor", the verb agrees with the nearer subject ("the two monitors" = plural) -> were.', 'Accurate grammatical choice (B) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000a4', 'Convert into reported speech:
Ananya asked Kabir, "Have you solved the Trigonometry sample paper?"', '{"A":"Ananya asked Kabir if he had solved the Trigonometry sample paper.","B":"Ananya asked Kabir had he solved the Trigonometry sample paper.","C":"Ananya told Kabir whether he solved the paper.","D":"Ananya asked Kabir if he has solved the Trigonometry sample paper."}'::jsonb, 'A', 'MCQ', 'English', 'Grammar', 1, 'Option (A) is correct. Yes/No question uses "if/whether" + statement word order + backshift Present Perfect ("have solved") to Past Perfect ("had solved").', 'Accurate grammatical choice (A) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000a5', 'Select the correct determiner: "There is still ________ hope left if we revise all NCERT diagrams tonight."', '{"A":"few","B":"many","C":"a little","D":"a few"}'::jsonb, 'C', 'MCQ', 'English', 'Grammar', 1, 'Option (C) is correct. "Hope" is an uncountable abstract noun -> "a little" (positive amount).', 'Accurate grammatical choice (C) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000a6', 'Identify the error and choose the correction in: "Each of the players were awarded a participation certificate."', '{"A":"Error: of -> in","B":"Error: were -> was","C":"Error: a -> an","D":"Error: awarded -> awarding"}'::jsonb, 'B', 'MCQ', 'English', 'Grammar', 1, 'Option (B) is correct. "Each of + plural noun" always takes a singular verb -> "was".', 'Accurate grammatical choice (B) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000a7', 'Report the doctor''s advice:
The doctor said to the patient, "Take this medicine twice daily after meals."', '{"A":"The doctor advised the patient to take that medicine twice daily after meals.","B":"The doctor ordered the patient take this medicine twice daily.","C":"The doctor asked the patient if he took that medicine.","D":"The doctor said the patient should took this medicine."}'::jsonb, 'A', 'MCQ', 'English', 'Grammar', 1, 'Option (A) is correct. Imperative advice reports using "advised ... to + V1" and "this" -> "that".', 'Accurate grammatical choice (A) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000a8', 'Complete: "If she ________ earlier, she would have caught the morning metro."', '{"A":"leaves","B":"left","C":"had left","D":"will leave"}'::jsonb, 'C', 'MCQ', 'English', 'Grammar', 1, 'Option (C) is correct. Third conditional ("would have caught") requires Past Perfect ("had left") in the if-clause.', 'Accurate grammatical choice (C) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000a9', 'Choose the right option: "Ten kilometres ________ a long distance to walk without water."', '{"A":"are","B":"were","C":"is","D":"have been"}'::jsonb, 'C', 'MCQ', 'English', 'Grammar', 1, 'Option (C) is correct. Specific distances, sums of money, and periods of time take a singular verb ("is").', 'Accurate grammatical choice (C) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000aa', 'Fill in: "Look at the wet streets; it ________ have rained heavily last night."', '{"A":"must","B":"shall","C":"ought","D":"dare"}'::jsonb, 'A', 'MCQ', 'English', 'Grammar', 1, 'Option (A) is correct. "Must have + V3" indicates strong logical deduction about a past event.', 'Accurate grammatical choice (A) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000ab', 'You are Aarav/Ananya residing at 42, Green Park Extension, New Delhi. Write a letter in 100–120 words to the Editor of a national daily expressing concern over broken streetlights and overflowing garbage bins in your neighbourhood park, suggesting practical civic measures.', NULL, NULL, 'LA', 'English', 'Writing', 5, '42, Green Park Extension
New Delhi – 110016

26 November 2026

The Editor
The Hindustan Times
New Delhi

Subject: Urgent concern over broken streetlights and poor sanitation in Green Park

Sir/Madam,

Through the columns of your esteemed newspaper, I wish to draw civic authorities'' attention to the deteriorating state of our neighbourhood park. Over the past month, six streetlights have remained non-functional, turning evening walks unsafe for senior citizens and children. Additionally, overflowing garbage bins attract stray animals and create unhygienic conditions.

I urge the Municipal Corporation to install LED solar streetlights, enforce twice-daily waste segregation clearance, and involve Resident Welfare Associations in weekly maintenance audits.

Yours sincerely,
Ananya', 'Format (Sender address, Date, Receiver, Subject, Salutation) [1 Mark] | Content (Problem + Actionable suggestions) [2 Marks] | Organisation of ideas [1 Mark] | Grammatical accuracy & spelling [1 Mark]', NULL, 'Examiner Tip: Keep format left-aligned without extra punctuation; always stay within 100–120 words. | Common Pitfall: Writing "Yours lovingly" instead of "Yours sincerely / Yours truly" in a formal letter.', 'HARD', true),
        ('10041111-0000-4000-8000-0000000000ac', 'The survey data below shows how students in a city school commute daily: Walking (32%), Cycling (24%), Public Bus (28%), Private Car/Two-wheeler (16%). Write an analytical paragraph in 100–120 words interpreting the distribution, highlighting eco-friendly trends and suggesting one improvement.', NULL, NULL, 'LA', 'English', 'Writing', 5, 'The given survey data illustrates daily commuting preferences among city school students, revealing an encouraging inclination toward sustainable transport. Over half of the students (56%) rely on zero-emission modes, with walking leading at 32% and cycling accounting for 24%. Public buses form the second-largest individual category at 28%, demonstrating strong reliance on shared transit. Conversely, private cars and two-wheelers represent the smallest segment at only 16%. Overall, 84% of learners already avoid private motorised vehicles. To further reduce traffic congestion near school gates and encourage that remaining 16%, school authorities and municipalities should develop dedicated shaded cycle tracks and safe pedestrian zebra crossings.', 'Clear topic sentence introducing data [1 Mark] | Accurate comparison of highest, lowest & combined shares [2 Marks] | Cohesive linkers (conversely, overall) [1 Mark] | Accuracy & conclusion [1 Mark]', NULL, 'Examiner Tip: Always group related data points (32% + 24% = 56% zero-emission) and use comparison words. | Common Pitfall: Adding personal fictional stories instead of objective data analysis.', 'HARD', true),
        ('10041111-0000-4000-8000-0000000000ad', 'Read the context carefully and answer:
In "A Letter to God", after a devastating hailstorm destroys his entire cornfield, Lencho writes a letter addressed directly "To God" asking for 100 pesos. Touched by his immense faith, the postmaster collects 70 pesos from colleagues and signs the envelope "God". Yet upon counting 70 pesos, Lencho becomes angry and writes a second letter calling the post office employees "a bunch of crooks".

Answer the questions (5 Marks):
(a) Why did Lencho need 100 pesos urgently? (1M)
(b) What motivated the postmaster to collect money for Lencho? (1M)
(c) Explain the central situational irony in Lencho calling the post office staff "a bunch of crooks". (2M)
(d) Identify a character trait of Lencho shown by his refusal to doubt God. (1M)', NULL, NULL, 'LA', 'English', 'Literature Extract (Prose)', 5, '(a) To sow his field again and support his family until the next harvest after hailstones ruined his crop.
(b) Initially amused, the postmaster soon felt deep admiration for Lencho''s unshakeable faith and wanted to keep that faith alive.
(c) The irony lies in the fact that the very employees who generously pooled 70 pesos out of charity to help Lencho were accused of stealing the missing 30 pesos.
(d) Unwavering, childlike faith (paired with misplaced suspicion of human helpers).', '(a) Re-sow field & survive until next crop [1 Mark] | (b) Preserve Lencho''s faith in God [1 Mark] | (c) Irony of blaming his real benefactors [2 Marks] | (d) Blind/unshakeable faith [1 Mark]', NULL, 'Examiner Tip: Always define the contrast between what Lencho believed and reality when explaining situational irony. | Common Pitfall: Saying the postmaster kept 30 pesos for himself!', 'HARD', true),
        ('10041111-0000-4000-8000-0000000000ae', 'Read the thematic context and answer:
In Robert Frost''s "Dust of Snow", a crow sitting in a hemlock tree shakes fine snow onto the speaker, instantly uplifting his gloomy mood and saving the rest of his day from regret.

Answer the questions (5 Marks):
(a) Name the poet of "Dust of Snow" and state what traditional symbols "crow" and "hemlock tree" represent. (2M)
(b) How does Frost invert the negative symbolism of crow and hemlock in this poem? (2M)
(c) State the rhyme scheme used in each quatrain of the poem. (1M)', NULL, NULL, 'LA', 'English', 'Literature Extract (Poetry)', 5, '(a) Poet: Robert Frost. Both the crow and the poisonous hemlock tree traditionally symbolise sorrow, bad omens, gloom, and death.
(b) Frost subverts these dark symbols by making them the agents of joy and healing—proving that even humble or seemingly negative aspects of nature can spark positivity.
(c) Rhyme scheme: abab.', '(a) Robert Frost + symbols of sorrow/gloom [2 Marks] | (b) Subversion: agents of positive mood shift [2 Marks] | (c) Rhyme scheme abab [1 Mark]', NULL, 'Examiner Tip: Remember both Robert Frost poems in Chapter 1 use nature imagery to explore human emotions. | Common Pitfall: Writing aabb instead of abab.', 'HARD', true),
        ('10041111-0000-4000-8000-0000000000af', 'How did the young seagull''s mother finally compel him to make his first flight? (40–50 words)', NULL, NULL, 'SA', 'English', 'First Flight', 3, 'Knowing her son was starving on the ledge, the mother flew close with a piece of fish in her beak and halted just out of reach. Maddened by hunger, the young seagull dived at the fish, fell outwards into space, and instinctively spread his wings to soar.', 'Core textual point & reasoning (2M) + Expression (1M) [3 Marks]', NULL, 'Examiner Tip: Highlight "maddened by hunger" as the psychological trigger. | Common Pitfall: Exceeding 50 words or missing exact character names.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000b0', 'Why does Anne Frank remark that "paper has more patience than people"? (40–50 words)', NULL, NULL, 'SA', 'English', 'First Flight', 3, 'Anne felt lonely without a true confidant to share her deepest thoughts. Unlike impatient humans who interrupt or judge, a diary listens quietly without losing patience, letting her express herself freely.', 'Core textual point & reasoning (2M) + Expression (1M) [3 Marks]', NULL, 'Examiner Tip: Connect to her naming her diary "Kitty". | Common Pitfall: Exceeding 50 words or missing exact character names.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000b1', 'What saddened eight-year-old Valli during her return bus journey, and what lesson did she learn? (40–50 words)', NULL, NULL, 'SA', 'English', 'First Flight', 3, 'On the return trip, Valli saw the same playful young cow she had laughed at earlier lying dead on the roadside, struck by a speeding vehicle. The sudden contrast between vibrant life and death dampened her excitement and matured her outlook.', 'Core textual point & reasoning (2M) + Expression (1M) [3 Marks]', NULL, 'Examiner Tip: Mention both her joy on onward trip and sorrow on return trip. | Common Pitfall: Exceeding 50 words or missing exact character names.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000b2', 'Why did Buddha ask Kisa Gotami to bring a handful of mustard seeds from a house where no one had ever died? (40–50 words)', NULL, NULL, 'SA', 'English', 'First Flight', 3, 'Buddha wanted Kisa Gotami to discover by herself—not merely hear—that death is universal and inevitable for every mortal family. Walking door-to-door helped her overcome selfish grief and accept mortality calmly.', 'Core textual point & reasoning (2M) + Expression (1M) [3 Marks]', NULL, 'Examiner Tip: Highlight experiential learning over mere lecturing. | Common Pitfall: Exceeding 50 words or missing exact character names.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000b3', 'Why did Hari Singh return the stolen ₹600 to Anil despite having a clear chance to board the Lucknow Express? (40–50 words)', NULL, NULL, 'SA', 'English', 'Footprints Without Feet', 3, 'Hari realised that while money could buy temporary luxuries, Anil was genuinely teaching him to read, write whole sentences, and add numbers—skills that could make him a respected, educated man for life. Anil''s unconditional trust melted Hari''s criminal instinct.', 'Core textual point & reasoning (2M) + Expression (1M) [3 Marks]', NULL, 'Examiner Tip: Mention both Anil''s trust AND the value of education. | Common Pitfall: Giving vague moral statements without textual incidents.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000b4', 'Why is Griffin considered a brilliant scientist yet a lawless person? (40–50 words)', NULL, NULL, 'SA', 'English', 'Footprints Without Feet', 3, 'Griffin discovered a rare drug making the human body transparent as glass—a monumental scientific feat. However, instead of using it for human welfare, he set his landlord''s house ablaze, stole clothes and cash, and assaulted innocent bystanders in Iping.', 'Core textual point & reasoning (2M) + Expression (1M) [3 Marks]', NULL, 'Examiner Tip: Always contrast scientific brilliance with moral misuse. | Common Pitfall: Giving vague moral statements without textual incidents.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000b5', 'Compare how determination and careful planning empower individuals to overcome fear or oppression, referencing BOTH "Madam Rides the Bus" (Valli) and "Nelson Mandela: Long Walk to Freedom". (100–120 words)', NULL, NULL, 'LA', 'English', 'First Flight Long Answer', 6, 'Both Valli and Nelson Mandela illustrate that courage combined with disciplined planning transforms seemingly impossible goals into reality, though on vastly different scales. Eight-year-old Valli turns her overwhelming desire for a bus ride into action through meticulous planning—saving sixty paise over months, resisting temptations like toys and peppermints, gathering route timings discreetly, and travelling independently with self-respect.

On a monumental historical scale, Nelson Mandela channelled unwavering resolve against brutal Apartheid. He understood that true courage is not the absence of fear, but triumph over it. Through years of sacrifice, endurance, and reconciliation, he transformed systemic oppression into a non-racial democracy. Together, both texts prove that clear vision and steady willpower conquer fear.', 'Reference Valli''s planning, thrift & independence [2.5 Marks] | Reference Mandela''s definition of courage & sacrifice [2.5 Marks] | Comparative conclusion & fluency [1 Mark]', NULL, 'Examiner Tip: In 6-mark comparative questions, explicitly address BOTH texts evenly. | Common Pitfall: Summarising only one chapter and forgetting the comparison.', 'HARD', true),
        ('10041111-0000-4000-8000-0000000000b6', 'Compassion, trust, and patient mentorship can reform a person or unlock hidden potential far better than punishment. Justify this statement with reference to "The Thief''s Story" (Anil) AND "Bholi" (Sulekha''s teacher). (100–120 words)', NULL, NULL, 'LA', 'English', 'Footprints Long Answer', 6, 'Both Ruskin Bond''s "The Thief''s Story" and K.A. Abbas''s "Bholi" demonstrate that empathy and trust possess far greater transformative power than fear or harshness.

In "The Thief''s Story", Anil welcomes young thief Hari Singh despite knowing he cannot cook, feeds him, pays him when possible, and teaches him to write. Even after discovering the damp stolen notes the next morning, Anil neither scolds Hari nor calls the police; his silent forgiveness permanently reforms Hari.

Similarly, in "Bholi", everyone mocks Sulekha for her pockmarks and stammer until her teacher speaks softly, gifts her a book, and nurtures self-belief. That steady encouragement gives Sulekha the courage to reject a greedy groom and vow to teach in her village. Kindness truly rebuilds human dignity.', 'Anil''s silent forgiveness & education transforming Hari [2.5 Marks] | Teacher''s patience empowering Sulekha against dowry [2.5 Marks] | Cohesive synthesis & language [1 Mark]', NULL, 'Examiner Tip: Highlight Anil''s wet notes silence and teacher''s soft voice as parallel turning points. | Common Pitfall: Retelling full plot instead of focusing on mentorship and compassion.', 'HARD', true),
        ('10041111-0000-4000-8000-0000000000b7', '[Read Passage: "Citizen Science and Urban Biodiversity Mapping"]
Every winter, thousands of school students, amateur photographers, and retired naturalists step into city parks and wetlands to record migratory birds, butterflies, and flowering trees using smartphone checklists. Known as "citizen science", this collaborative model has transformed ecological monitoring in India. Professional biologists alone cannot survey every neighbourhood lake simultaneously, whereas trained volunteers upload thousands of time-stamped, geo-tagged sightings in a single weekend. Researchers verify unusual sightings through photographic evidence, using aggregated maps to detect shifts in bird migration timing linked to warming winters and shrinking wetland buffers.

What is "citizen science" as described in the passage?', '{"A":"Private ownership of parks","B":"Public participation of non-specialists collecting verified ecological sightings","C":"Banning smartphones inside forests","D":"Paid government census surveys only"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. Students, amateurs and naturalists record geo-tagged ecological sightings via smartphone checklists.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000b8', '[From Passage "Citizen Science and Urban Biodiversity Mapping"] How do researchers maintain accuracy in citizen-collected sightings?', '{"A":"By deleting weekend uploads","B":"By verifying unusual sightings through photographic evidence","C":"By counting only indoor specimens","D":"By ignoring volunteer checklists"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. Researchers verify unusual sightings using photographic evidence.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000b9', '[From Passage "Citizen Science and Urban Biodiversity Mapping"] Why are citizen volunteers valuable alongside professional biologists?', '{"A":"Professionals cannot survey every neighbourhood lake simultaneously","B":"Volunteers manufacture satellite cameras","C":"Biologists do not study birds","D":"Lakes exist only in winter"}'::jsonb, 'A', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (A) is correct. Volunteers dramatically expand geographic and simultaneous sampling coverage.', 'Correct option (A) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000ba', '[From Passage "Citizen Science and Urban Biodiversity Mapping"] Which term means "combined or collected into a single whole"?', '{"A":"Simultaneous","B":"Aggregated","C":"Shrinking","D":"Migratory"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. "Aggregated maps" means combined data collected from many volunteers.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000bb', '[From Passage "Citizen Science and Urban Biodiversity Mapping"] Aggregated biodiversity maps help scientists detect changes in:', '{"A":"Smartphone battery life","B":"Bird migration timing tied to warming winters and shrinking wetlands","C":"Concrete density in cities","D":"Ticket prices at zoos"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. Maps detect shifts in migration timing linked to warming winters and wetland loss.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000bc', '[From Passage "Citizen Science and Urban Biodiversity Mapping"] What two metadata tags accompany volunteer checklist uploads?', '{"A":"Price and weight","B":"Time-stamps and geo-tags","C":"Age and height","D":"Passwords and fees"}'::jsonb, 'B', 'MCQ', 'English', 'Reading Comprehension', 1, 'Option (B) is correct. Volunteers upload time-stamped, geo-tagged sightings.', 'Correct option (B) from passage evidence [1 Mark]', NULL, 'Examiner Tip: Locate the exact phrase in the passage before selecting. | Common Pitfall: Relying on outside knowledge rather than passage facts.', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000bd', '[From Passage "Citizen Science and Urban Biodiversity Mapping"] Explain how school students contribute meaningfully to ecological conservation through citizen science.', NULL, NULL, 'VSA', 'English', 'Reading Comprehension', 2, 'By documenting local birds, butterflies and trees with time-stamped photographs on checklists, students supply widespread baseline data that alerts researchers early to declining wetlands or altered migration schedules.', 'Two clear passage-supported points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase neatly in your own words without exceeding 40 words. | Common Pitfall: Copying an entire paragraph verbatim.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000be', '[From Passage "Citizen Science and Urban Biodiversity Mapping"] Give two challenges or threats to urban birds highlighted indirectly by the passage.', NULL, NULL, 'VSA', 'English', 'Reading Comprehension', 2, 'The passage points to warming winter temperatures altering migration timing and shrinking wetland buffers reducing critical urban stopover habitats.', 'Two clear passage-supported points (30-40 words) [2 Marks]', NULL, 'Examiner Tip: Paraphrase neatly in your own words without exceeding 40 words. | Common Pitfall: Copying an entire paragraph verbatim.', 'MEDIUM', true),
        ('10041111-0000-4000-8000-0000000000bf', 'Choose the right option: "Hardly ________ students attended the extra remedial session during holidays."', '{"A":"much","B":"any","C":"little","D":"less"}'::jsonb, 'B', 'MCQ', 'English', 'Grammar', 1, 'Option (B) is correct. "Hardly" carries negative force and pairs naturally with "any" before plural countable nouns.', 'Accurate grammatical choice (B) [1 Mark]', NULL, 'Examiner Tip: Check tense agreement and subject-verb number first. | Common Pitfall: Missing subtle tense markers like "since" or "had".', 'EASY', true),
        ('10041111-0000-4000-8000-0000000000c0', 'You are Priya/Pranav, Librarian at Kendriya Vidyalaya, Sector 8, Chandigarh. Write a letter in 100–120 words to M/s Sunrise Publishers, Daryaganj, New Delhi, complaining about receiving 15 damaged copies out of a consignment of 60 Class 10 Reference Books and requesting immediate replacement.', NULL, NULL, 'LA', 'English', 'Writing', 5, 'The Librarian
Kendriya Vidyalaya, Sector 8
